            (
                head? - Vec3::Y * TORSO_FOCUS_BELOW_HEAD_METRES,
                TORSO_REVIEW_DISTANCE_METRES,
                0.0,
            )
        } else {
            (
                subject.translation,
                REVIEW_CAMERA_DISTANCE_METRES,
