        )
        .unwrap();
        assert!(stop.uses_flat_grid());
        assert!(
            stop.plan[..48]
                .iter()
                .all(|frame| frame.speed == authored_drive_speed(2.0))
        );
        assert!(
            stop.plan[56..]
                .iter()
                .all(|frame| frame.speed == SignedSpeed::ZERO)
        );
        assert!(
            stop.plan[48..=56]
                .windows(2)
                .all(|pair| pair[1].speed <= pair[0].speed)
        );
