261: pub(super) fn kick_bones(
262:     mut kicks: MessageReader<BoneKick>,
263:     mut rigs: Query<(&HumanoidRig, &mut BouncyBones)>,
264:     globals: Query<&GlobalTransform>,
265: ) {
266:     let tuning = bounce_tuning();
267:     for kick in kicks.read() {
268:         let Ok((rig, mut bones)) = rigs.get_mut(kick.owner) else {
269:             continue;
270:         };
271:         let Some(start) = bone_index(kick.role) else {
272:             continue;
273:         };
274:         let mut index = start;
275:         let mut gain = tuning.strength;
276:         loop {
277:             if let Some(direction) = bone_direction(index, rig, &globals) {
278:                 // `direction × impulse` is the angular kick that swings the
279:                 // tip the way the shove goes.
280:                 let spin = direction.cross(kick.impulse);
281:                 bones.springs[index].velocity += spin * (reactive_bone(index).response * gain);
282:             }
283:             gain *= tuning.transmission;
284:             match reactive_bone(index).parent {
285:                 Some(parent) if gain > 0.02 => index = parent,
286:                 _ => break,
287:             }
288:         }
289:     }
290: }
