218: /// Exact damped-oscillator step, solved per axis: the equation is linear and
219: /// isotropic, so the scalar solution applies to the whole vector. The
220: /// damping comes from the envelope half-life and the frequency from the
221: /// tuned wobble rate; the damped frequency is clamped so an overdamped
222: /// request degrades to near-critical instead of producing a NaN.
223: fn spring_step(spring: &mut Spring, halflife: f32, frequency: f32, delta_seconds: f32) {
224:     let decay = std::f32::consts::LN_2 / halflife.max(1e-3);
225:     let omega = std::f32::consts::TAU * frequency.max(0.01);
226:     let damped = (omega * omega - decay * decay).max(1e-4).sqrt();
227:     let envelope = (-decay * delta_seconds).exp();
228:     let (sin, cos) = (damped * delta_seconds).sin_cos();
229:     let b = (spring.velocity + spring.offset * decay) / damped;
230:     let offset = (spring.offset * cos + b * sin) * envelope;
231:     let velocity = (spring.velocity * cos - (spring.offset * damped + b * decay) * sin) * envelope;
232:     // Snap the tail to true zero so at-rest rigs skip the hierarchy walk.
233:     if offset.length_squared() < 1e-8 && velocity.length_squared() < 1e-8 {
234:         *spring = Spring::default();
235:     } else {
236:         *spring = Spring { offset, velocity };
237:     }
238: }
