51:     let global_bone_trace_path = output.join("global-bone-transforms.jsonl");
52:     let trace_file = File::create(&global_bone_trace_path)
53:         .unwrap_or_else(|error| panic!("failed to create {global_bone_trace_path:?}: {error}"));
54:     let mut trace_writer = BufWriter::new(trace_file);
55:     for frame in &global_bone_frames {
56:         serde_json::to_writer(&mut trace_writer, frame).unwrap_or_else(|error| {
57:             panic!("failed to serialize {global_bone_trace_path:?}: {error}")
58:         });
59:         trace_writer
60:             .write_all(b"\n")
61:             .unwrap_or_else(|error| panic!("failed to write {global_bone_trace_path:?}: {error}"));
62:     }
63:     trace_writer
64:         .flush()
65:         .unwrap_or_else(|error| panic!("failed to flush {global_bone_trace_path:?}: {error}"));
66:     let manifest_path = output.join("manifest.json");
