1: //! Cloud lattice samples and weather-context seed derivation.
2: use super::*;
3: use fabelgeist_determinism::Seed;
4: 
5: pub(super) fn non_periodic_value_noise_3d(position: CloudDensityCoordinate, seed: Seed) -> f32 {
6:     // Native numerical kernel: dimensionless density-lattice axes, never metres.
7:     let position = position.axes();
8:     let cell = position.floor();
9:     let fraction = position - cell;
10:     // Quintic interpolation makes both first and second derivatives vanish at
11:     // lattice boundaries. The cloud field is magnified over kilometres, so
12:     // the cubic value-noise shoulder was still legible as broad square cells.
13:     let smooth = fraction
14:         * fraction
15:         * fraction
16:         * (fraction * (fraction * 6.0 - Vec3::splat(15.0)) + Vec3::splat(10.0));
17:     let value = |offset: Vec3| {
18:         let lattice = cell + offset;
19:         streams::LATTICE
20:             .rng(
21:                 seed,
22:                 &[
23:                     lattice.x as i64 as u64,
24:                     lattice.y as i64 as u64,
25:                     lattice.z as i64 as u64,
26:                 ],
27:             )
28:             .inclusive_unit_f32()
29:     };
30:     let x0 = value(Vec3::ZERO).lerp(value(Vec3::X), smooth.x);
31:     // The z=0 upper-X corner is (1, 1, 0). Sampling (1, 1, 1) here coupled
32:     // adjacent Z cells and exposed axis-aligned macro blocks in the dome bake.
33:     let x1 = value(Vec3::Y).lerp(value(Vec3::X + Vec3::Y), smooth.x);
34:     let y0 = x0.lerp(x1, smooth.y);
35:     let x2 = value(Vec3::Z).lerp(value(Vec3::Z + Vec3::X), smooth.x);
36:     let x3 = value(Vec3::Z + Vec3::Y).lerp(value(Vec3::ONE), smooth.x);
37:     y0.lerp(x2.lerp(x3, smooth.y), smooth.z)
38: }
