56: /// Dimensionless displacement of the density lattice; never a world position.
57: pub(super) fn density_warp(
58:     coordinate: CloudDensityCoordinate,
59:     seed: fabelgeist_determinism::Seed,
60:     slot: ActiveCloudLayerOrdinal,
61: ) -> CloudDensityWarp {
62:     use super::streams;
63:     CloudDensityWarp(
64:         Vec3::new(
65:             non_periodic_value_noise_3d(
66:                 coordinate * 0.36,
67:                 streams::WARP_X.seed(seed, &[slot.context_word()]),
68:             ),
69:             non_periodic_value_noise_3d(
70:                 coordinate * 0.36 + Vec3::splat(13.7),
71:                 streams::WARP_Y.seed(seed, &[slot.context_word()]),
72:             ),
73:             non_periodic_value_noise_3d(
74:                 coordinate * 0.36 + Vec3::new(4.1, 9.7, 17.3),
75:                 streams::WARP_Z.seed(seed, &[slot.context_word()]),
76:             ),
77:         ) - Vec3::splat(0.5),
78:     )
79: }
