41:     fabelgeist_determinism::Seed::derive(
42:         environment.scene_digest.as_bytes(),
43:         streams::ENVIRONMENT,
44:         &[
45:             &environment
46:                 .absolute_minute
47:                 .period_index(360)
48:                 .expect("cloud seed period must be nonzero")
49:                 .to_le_bytes(),
50:             &environment.latitude_microdegrees.get().to_le_bytes(),
51:             &environment.longitude_microdegrees.get().to_le_bytes(),
52:         ],
53:     )
54: }
