56: /// Dimensionless displacement of the density lattice; never a world position.
57: pub(super) fn density_warp(
58:     coordinate: CloudDensityCoordinate,
59:     seed: fabelgeist_determinism::Seed,
60:     slot: ActiveCloudLayerOrdinal,
61: ) -> CloudDensityWarp {
