43: /// Fires whenever `SceneTerrain` lands on any entity - via fresh procedural
44: /// generation in `on_server_started` or a loaded world dump
45: /// (`load_world_dump`). Derives independent static collision bodies from the
46: /// immutable terrain and adds the replication marker. Colliders aren't reflectable
47: /// and so never survives a dump on its own; a dump only needs to carry the
48: /// "core" `SceneId`/`SceneTerrain`/`Transform`.
49: pub(crate) fn on_scene_terrain_added(
50:     event: On<Add, SceneTerrain>,
51:     mut commands: Commands,
52:     query: Query<(
53:         &SceneTerrain,
54:         Option<&TerrainLandformRecipe>,
55:         Option<&SceneTerrainPatch>,
56:     )>,
57: ) -> Result {
58:     let (terrain, recipe, prepared) = query.get(event.entity)?;
59:     let colliders = terrain_collision::colliders(terrain, recipe, prepared)?;
60:     commands
61:         .entity(event.entity)
62:         .insert(Replicated)
63:         .remove::<SceneTerrainPatch>()
64:         .with_children(|parent| {
65:             for collider in colliders {
66:                 parent.spawn((
67:                     RigidBody::Static,
68:                     CollisionLayers::new(TACTICAL_TERRAIN_LAYER, LayerMask::ALL),
69:                     collider,
70:                     Transform::IDENTITY,
71:                 ));
72:             }
73:         });
74:     Ok(())
75: }

