15: pub trait AppRuleExt {
16:     /// Defines a [`ReplicationRule`] for a single component.
17:     ///
18:     /// If present on an entity with [`Replicated`] component,
19:     /// it will be serialized and deserialized as-is using [`postcard`]
20:     /// and sent at [`ReplicationMode::OnChange`]. To customize this, use [`Self::replicate_with`].
21:     ///
22:     /// See also the [components section](crate#components) from the quick start guide.
23:     fn replicate<C>(&mut self) -> &mut Self
24:     where
25:         C: Component<Mutability: MutWrite<C>> + Serialize + DeserializeOwned,
26:     {
27:         self.replicate_filtered::<C, ()>()
28:     }
29: 
30:     /// Like [`Self::replicate`], but uses [`ReplicationMode::Once`].
31:     fn replicate_once<C>(&mut self) -> &mut Self
32:     where
33:         C: Component<Mutability: MutWrite<C>> + Serialize + DeserializeOwned,
34:     {
35:         self.replicate_once_filtered::<C, ()>()
36:     }
37: 
38:     /// Like [`Self::replicate`], but sends recorded diffs instead of re-sending
39:     /// the entire component when it changes.
40:     ///
41:     /// Mutations should be performed through [`EntityCommandsDiffExt::apply_diff`]
42:     /// or [`EntityDiffExt::apply_diff`].
43:     ///
44:     /// See [`Diffable`] for more details.
45:     fn replicate_diff<C>(&mut self) -> &mut Self
46:     where
47:         C: Diffable,
48:     {
49:         self.replicate_diff_filtered::<C, ()>()
50:     }
51: 
52:     /// Like [`Self::replicate_diff`], but also adds filters like [`Self::replicate_filtered`].
53:     fn replicate_diff_filtered<C, F: FilterRules>(&mut self) -> &mut Self
54:     where
55:         C: Diffable,
56:     {
57:         self.replicate_with_filtered::<_, F>(RuleFns::<C>::new_diff())
58:     }
