971:     state: &mut CloudBakeState,
972:     material: &mut TacticalCloudMaterial,
973:     images: &mut Assets<Image>,
974:     completed: CompletedCloudBake,
975: ) -> Option<CloudBakeRequest> {
976:     if state.key.as_ref() != Some(&completed.request.key) {
977:         return None;
