989:         *image = completed.image;
990:     }
991:     state.end_ready = true;
992:     state.elapsed_seconds = 0.0;
993:     Some(CloudBakeRequest {
994:         key: completed.request.key,
995:         endpoint: completed.request.endpoint + 1,
