13: impl CloudBakeRequest {
14:     /// Integrate a native unit dome ray in the metre-based, Y-up bake frame.
15:     /// The RGBA8 result is the image boundary; no extra ray normalization changes
16:     /// the authored angular lattice or the integration arithmetic.
17:     pub(super) fn integrated_pixel(&self, direction: Vec3) -> [u8; 4] {
18:         let reference_eye = Vec3::new(0.0, CLOUD_BAKE_REFERENCE_EYE_METRES, 0.0);
19:         let advection_metres = self.advection_metres();
20:         let evolution = self.evolution();
21:         let mut optical_depth = 0.0;
22:         let mut lighting = 0.0;
23:         let mut variation = 0.0;
24:         for (slot, layer) in self.key.layers.iter().flatten().enumerate() {
25:             let Some((start, end)) = cloud_ray_layer_interval(reference_eye, direction, *layer)
26:             else {
27:                 continue;
28:             };
29:             let step = (end - start) / CLOUD_BAKE_VERTICAL_SAMPLES as f32;
30:             for sample in 0..CLOUD_BAKE_VERTICAL_SAMPLES {
31:                 let distance = start + (sample as f32 + 0.5) * step;
32:                 let position = reference_eye + direction * distance;
33:                 let height = ((cloud_shell_altitude(position) - layer.bottom_metres)
34:                     / layer.thickness_metres)
35:                     .clamp(0.0, 1.0);
36:                 let density = baked_cloud_density(
37:                     position.xz() - advection_metres,
38:                     height,
39:                     *layer,
40:                     self.key.seed,
41:                     ActiveCloudLayerOrdinal::new(slot),
42:                     evolution,
43:                 );
44:                 let contribution = density * step * 0.001_45;
45:                 optical_depth += contribution;
46:                 let detail = cloud_bake_lighting_variation(
47:                     position.xz() - advection_metres,
48:                     height,
49:                     *layer,
50:                     self.key.seed,
51:                     ActiveCloudLayerOrdinal::new(slot),
52:                     evolution,
53:                 );
54:                 lighting += contribution * (0.18 + height * 0.76) * (0.18 + detail * 0.82);
55:                 variation += contribution * detail;
56:             }
57:         }
58:         let alpha = 1.0 - (-optical_depth).exp();
59:         let lighting = if optical_depth > 0.0001 {
60:             lighting / optical_depth
61:         } else {
62:             0.0
63:         };
64:         let variation = if optical_depth > 0.0001 {
65:             variation / optical_depth
66:         } else {
67:             0.0
68:         };
69:         let sun_transmission = (-optical_depth * (0.45 + variation * 0.55)).exp();
70:         [
71:             (alpha * 255.0).round() as u8,
72:             (lighting.clamp(0.0, 1.0) * 255.0).round() as u8,
73:             (sun_transmission * 255.0).round() as u8,
74:             (variation.clamp(0.0, 1.0) * 255.0).round() as u8,
75:         ]
76:     }
77: }
