36: fn ray_sphere_roots(
37:     ray_origin: vec3<f32>,
38:     ray_direction: vec3<f32>,
39:     radius: f32,
40: ) -> vec2<f32> {
41:     let relative_origin = ray_origin - shell_center();
42:     let projected = dot(relative_origin, ray_direction);
43:     let discriminant = projected * projected
44:         - (dot(relative_origin, relative_origin) - radius * radius);
45:     if discriminant < 0.0 {
46:         return vec2<f32>(-1.0, -1.0);
