52: fn cloud_coordinate(ray_direction: vec3<f32>) -> vec2<f32> {
53:     let azimuth = atan2(ray_direction.z, ray_direction.x) / (2.0 * 3.14159265359) + 0.5;
54:     let elevation = asin(clamp(ray_direction.y, 0.0, 1.0)) / (0.5 * 3.14159265359);
