20:     mut clock: Local<ProgressClock>,
21:     state: Option<Res<ScenePerformanceBenchmarkState>>,
22:     cloud: Res<TacticalCloudAnimationStatus>,
23: ) {
24:     let Some(state) = state else {
25:         return;
