556: fn baked_cloud_density(
557:     world: Vec2,
558:     height: f32,
559:     layer: CloudLayerParameters,
560:     seed: Seed,
561:     slot: ActiveCloudLayerOrdinal,
562:     evolution: f32,
563: ) -> f32 {
564:     let kind = layer.profile as u32;
565:     let coordinate = cloud_density_coordinate(world, height, layer, seed, evolution);
566:     // Broad coverage, domain warp, and fine erosion all sample a genuine
567:     // finite 3-D lattice. Height is an independent coordinate, not a planar
568:     // translation, so integrating a ray cannot turn a single 2-D field into
569:     // radial wedges.
570:     let warp = noise::density_warp(coordinate, seed, slot);
571:     let warped = coordinate + warp * Vec3::new(0.85, 0.42, 0.85);
572:     // Three incommensurate, non-periodic frequencies form clustered lobes;
573:     // no individual octave can reveal a repeated cell over the dome.
574:     let broad = non_periodic_value_noise_3d(
575:         warped * 0.58,
576:         streams::BROAD.seed(seed, &[slot.context_word()]),
577:     ) * 0.29
578:         + non_periodic_value_noise_3d(
579:             warped * 1.23,
580:             streams::MEDIUM.seed(seed, &[slot.context_word()]),
581:         ) * 0.44
582:         + non_periodic_value_noise_3d(
583:             warped * 2.61,
584:             streams::FINE.seed(seed, &[slot.context_word()]),
585:         ) * 0.27;
586:     let detail = non_periodic_value_noise_3d(
587:         warped * 5.9 + Vec3::new(9.7, 1.3, 4.1),
588:         streams::DETAIL.seed(seed, &[slot.context_word()]),
589:     );
590:     let profile = cloud_vertical_profile(height, kind, broad);
591:     let mut threshold = 0.78 - layer.coverage * 0.34;
592:     if matches!(kind, 4 | 6 | 7 | 9) {
593:         threshold -= 0.08;
594:     }
595:     if kind == 0 {
596:         // Representative fair-weather coverage needs cores above the stable
597:         // tactical reference point, not only at long grazing paths.
598:         threshold += height * 0.07 - 0.24;
599:     }
600:     if kind == 3 {
601:         threshold += height * 0.24 - smoothstep(0.68, 0.82, height) * 0.11;
602:         threshold -= 0.10;
603:     }
604:     if kind == 10 {
605:         threshold += height * 0.14;
606:     }
607:     let body = if matches!(kind, 4 | 6 | 7 | 9) {
608:         smoothstep(threshold, threshold + 0.17, broad) * (0.58 + detail * 0.50)
609:     } else {
610:         smoothstep(threshold, threshold + 0.16, broad - (1.0 - detail) * 0.20)
611:     };
612:     (body * profile * layer.density).clamp(0.0, 1.35)
613: }
