615: fn cloud_density_coordinate(
616:     world: Vec2,
617:     height: f32,
618:     layer: CloudLayerParameters,
619:     seed: Seed,
620:     evolution: f32,
621: ) -> CloudDensityCoordinate {
622:     let family_scale = match layer.profile as u32 {
623:         2 => Vec2::new(0.32, 1.8),
624:         5 | 8 => Vec2::splat(1.75),
625:         4 | 6 | 7 | 9 => Vec2::splat(0.58),
626:         _ => Vec2::ONE,
627:     };
628:     let seed_offset = layer.seed + (seed.to_u64() & 0x0fff) as f32;
629:     let mut coordinate = Vec3::new(
630:         world.x * layer.horizontal_scale + seed_offset * 0.013,
631:         height * 1.8 + seed_offset * 0.007,
632:         world.y * layer.horizontal_scale - seed_offset * 0.011,
633:     );
634:     // Slow non-rigid evolution changes cell edges between endpoints. Known
635:     // horizontal wind translation is handled separately and removed by the
636:     // runtime warp before the two optical solutions are blended.
637:     coordinate += Vec3::new(evolution * 0.37, evolution, -evolution * 0.23);
638:     coordinate.x *= family_scale.x;
639:     coordinate.z *= family_scale.y;
640:     CloudDensityCoordinate::from_layer_axes(coordinate)
641: }
