470: fn validate_weather(weather: WeatherSnapshot) -> SceneInputResult<()> {
471:     if weather.rules_version != WEATHER_RULES_VERSION
472:         || weather.wind_speed_bps > BASIS_POINTS_PER_WHOLE
473:         || weather.intensity_bps > BASIS_POINTS_PER_WHOLE
474:         || weather.ground_moisture_bps > BASIS_POINTS_PER_WHOLE
475:         || weather.snow_cover_bps > BASIS_POINTS_PER_WHOLE
476:         || weather.atmosphere.relative_humidity_bps > BASIS_POINTS_PER_WHOLE
477:         || weather.atmosphere.dew_point_deci_c > weather.temperature_deci_c + 5
478:         || !(8_700..=10_850).contains(&weather.atmosphere.sea_level_pressure_deci_hpa)
479:         || weather.atmosphere.wind_direction_degrees >= 360
480:         || weather.atmosphere.wind_shear_bps > BASIS_POINTS_PER_WHOLE
481:         || weather.atmosphere.instability_bps > BASIS_POINTS_PER_WHOLE
482:         || !(-i16::try_from(BASIS_POINTS_PER_WHOLE).unwrap()
483:             ..=i16::try_from(BASIS_POINTS_PER_WHOLE).unwrap())
484:             .contains(&weather.atmosphere.lift_bps)
485:         || weather.cloud_layers().any(|layer| {
486:             layer.coverage_bps > BASIS_POINTS_PER_WHOLE
487:                 || layer.optical_density_bps > BASIS_POINTS_PER_WHOLE
488:                 || layer.top_metres <= layer.base_metres
489:         })
490:         || (matches!(weather.precipitation, Precipitation::Clear) && weather.intensity_bps != 0)
491:         || (!matches!(weather.precipitation, Precipitation::Clear)
492:             && (weather.intensity_bps == 0
493:                 || !weather.cloud_layers().any(|layer| {
494:                     matches!(
495:                         layer.form,
496:                         adventuresim_core::weather::CloudForm::Cumulonimbus
497:                             | adventuresim_core::weather::CloudForm::Nimbostratus
498:                     )
499:                 })))
500:     {
501:         return invalid(SceneValidationError::Weather);
502:     }
503:     Ok(())
504: }
