10: const ANIMATION_MISSION_COORDINATE_PREFIX: &str = "animation-";
11: const DIAGNOSTIC_MISSION_COORDINATE_PREFIX: &str = "diagnostic-";
12: const STANDALONE_DIAGNOSTIC_SITE_DISTANCE_M: u64 = 2_000;
13: const METERS_PER_GEOGRAPHIC_LATITUDE_DEGREE: f64 = 111_000.0;
14: const METERS_PER_UNBOUNDED_COORDINATE_UNIT: f64 = 1_000.0;
15: 
16: impl StandaloneMissionFamily {
17:     pub(super) fn from_mission_id(mission_id: &str) -> Result<Self, String> {
18:         let mission_id = adventuresim_core::mission::MissionId::new(mission_id)
19:             .map_err(|_| "Standalone mission ID has an invalid domain coordinate".to_owned())?;
20:         let (_, coordinate) = mission_id
21:             .as_str()
22:             .split_once(':')
23:             .expect("validated mission IDs contain a domain separator");
24:         if let Some(animation_coordinate) =
25:             coordinate.strip_prefix(ANIMATION_MISSION_COORDINATE_PREFIX)
26:         {
27:             if animation_coordinate.is_empty() {
28:                 return Err("Animation mission ID has no coordinate".into());
29:             }
30:             Ok(Self::Animation)
31:         } else if let Some(diagnostic_coordinate) =
32:             coordinate.strip_prefix(DIAGNOSTIC_MISSION_COORDINATE_PREFIX)
33:         {
34:             if diagnostic_coordinate.is_empty() {
35:                 return Err("Diagnostic mission ID has no coordinate".into());
36:             }
37:             Ok(Self::Diagnostic)
38:         } else {
39:             Ok(Self::General)
40:         }
41:     }
