43:     pub(super) fn case_site_distance_m(self) -> u64 {
44:         match self {
45:             Self::Diagnostic => STANDALONE_DIAGNOSTIC_SITE_DISTANCE_M,
46:             Self::Animation | Self::General => 0,
47:         }
48:     }
49: }
