51: pub(super) fn standalone_case_site_northward_offset(
52:     distance_m: u64,
53:     coordinates_are_geographic: bool,
54: ) -> f64 {
55:     let coordinate_unit_m = if coordinates_are_geographic {
56:         METERS_PER_GEOGRAPHIC_LATITUDE_DEGREE
57:     } else {
58:         METERS_PER_UNBOUNDED_COORDINATE_UNIT
59:     };
60:     distance_m as f64 / coordinate_unit_m
61: }
