11: /// Whether finite geographic coordinates fall inside inclusive WGS84 bounds.
12: pub fn coordinates_in_bounds(longitude: f64, latitude: f64, bounds: [f64; 4]) -> bool {
13:     let [west, south, east, north] = bounds;
14:     longitude.is_finite()
15:         && latitude.is_finite()
16:         && longitude >= west
17:         && longitude <= east
18:         && latitude >= south
19:         && latitude <= north
