38:         let scaled = value * f64::from(Self::UNITS_PER_COORDINATE_UNIT);
39:         if !scaled.is_finite() || !(f64::from(i32::MIN)..=f64::from(i32::MAX)).contains(&scaled) {
40:             return None;
41:         }
42:         Some(Self(scaled.round() as i32))
43:     }
