1: //! Correlated fixed-point weather lattice and interpolation.
2: use super::*;
3: use fabelgeist_determinism::Seed;
4: 
5: /// Smooth deterministic field with synoptic-scale spatial correlation,
6: /// eastward advection, and day-scale evolution.
7: pub(super) fn correlated_field(
8:     seed: Seed,
9:     domain: StreamId,
10:     interval: u64,
11:     lat: i32,
12:     lon: i32,
13: ) -> u16 {
14:     let interval = interval.min(i64::MAX as u64 / (4 * FIELD_FRACTION as u64)) as i64;
15:     let x = i64::from(lon) * FIELD_FRACTION - interval * 4 * FIELD_FRACTION;
16:     let y = i64::from(lat) * FIELD_FRACTION + interval * FIELD_FRACTION;
17:     let t = interval * FIELD_FRACTION / SYNOPTIC_TIME_INTERVALS;
18:     let spatial_scale = SYNOPTIC_SPATIAL_CELLS * FIELD_FRACTION;
19:     let x0 = x.div_euclid(spatial_scale);
20:     let y0 = y.div_euclid(spatial_scale);
21:     let t0 = t.div_euclid(FIELD_FRACTION);
22:     let xf = fade_fraction(x.rem_euclid(spatial_scale), spatial_scale);
23:     let yf = fade_fraction(y.rem_euclid(spatial_scale), spatial_scale);
24:     let tf = fade_fraction(t.rem_euclid(FIELD_FRACTION), FIELD_FRACTION);
25:     let sample = |dx: i64, dy: i64, dt: i64| {
26:         domain
27:             .rng(
28:                 seed,
29:                 &[
30:                     u64::from(WEATHER_RULES_VERSION),
31:                     (t0 + dt) as u64,
32:                     (y0 + dy) as u64,
33:                     (x0 + dx) as u64,
34:                 ],
35:             )
36:             .index(usize::from(BASIS_POINTS_PER_WHOLE) + 1) as u16
37:     };
38:     let lower = lerp_bps(
39:         lerp_bps(sample(0, 0, 0), sample(1, 0, 0), xf),
40:         lerp_bps(sample(0, 1, 0), sample(1, 1, 0), xf),
41:         yf,
42:     );
43:     let upper = lerp_bps(
44:         lerp_bps(sample(0, 0, 1), sample(1, 0, 1), xf),
45:         lerp_bps(sample(0, 1, 1), sample(1, 1, 1), xf),
46:         yf,
47:     );
48:     lerp_bps(lower, upper, tf)
49: }
50: 
51: pub(super) fn fade_fraction(remainder: i64, scale: i64) -> u32 {
52:     let fraction = (remainder as u64 * 65_535 / scale as u64) as u32;
53:     let f = u64::from(fraction);
54:     ((f * f * (3 * 65_535 - 2 * f)) / (65_535 * 65_535)) as u32
55: }
56: 
57: pub(super) fn lerp_bps(a: u16, b: u16, fraction: u32) -> u16 {
58:     let a = i64::from(a);
59:     let delta = i64::from(b) - a;
60:     (a + delta * i64::from(fraction) / 65_535).clamp(0, i64::from(BASIS_POINTS_PER_WHOLE)) as u16
61: }
