708: pub(super) fn contact_to_passing_height_gain(frames: &[&FrameSample]) -> f32 {
709:     let frames = phase_validation_frames(frames);
710:     let phase_distance = |phase: f32, target: f32| {
711:         let distance = (phase - target).abs();
712:         distance.min(1.0 - distance)
713:     };
714:     let contact = frames
715:         .iter()
716:         .filter(|frame| {
717:             phase_distance(frame.gait_phase.cycles(), 0.0) <= 0.04
718:                 || phase_distance(frame.gait_phase.cycles(), 0.5) <= 0.04
719:         })
720:         .filter_map(|frame| body_local(frame, BoneRole::Pelvis).map(|pelvis| pelvis.y))
721:         .fold(f32::NEG_INFINITY, f32::max);
722:     let passing = frames
723:         .iter()
724:         .filter(|frame| {
725:             phase_distance(frame.gait_phase.cycles(), 0.25) <= 0.04
726:                 || phase_distance(frame.gait_phase.cycles(), 0.75) <= 0.04
727:         })
728:         .filter_map(|frame| body_local(frame, BoneRole::Pelvis).map(|pelvis| pelvis.y))
729:         .fold(f32::INFINITY, f32::min);
730:     if contact.is_finite() && passing.is_finite() {
731:         passing - contact
732:     } else {
733:         0.0
734:     }
735: }
