134:     /// Run a SQL query and decode exact generated rows through SATS rather
135:     /// than through hand-maintained serde mirrors.
136:     pub async fn query_sats<T: SatsDeserializeOwned>(&self, sql: &str) -> Result<Vec<T>> {
137:         let query_response = self.query_response(sql).await?;
138:         decode_sats_query_response(&query_response)
139:     }
140: 
141:     /// Run a generated-row query that should return at most one row.
142:     pub async fn query_one_sats<T: SatsDeserializeOwned>(&self, sql: &str) -> Result<Option<T>> {
143:         let mut rows = self.query_sats(sql).await?;
144:         if rows.len() > 1 {
145:             return Err(SpacetimeError::Spacetime(format!(
146:                 "query expected at most one row but returned {}: {sql}",
147:                 rows.len()
148:             )));
149:         }
150:         Ok(rows.pop())
151:     }
152: 
153:     /// Decode exact generated rows first, then apply an explicit presentation
154:     /// projection. This keeps schema validation on the generated SATS owner.
155:     pub async fn query_sats_into<T, U>(&self, sql: &str) -> Result<Vec<U>>
156:     where
157:         T: SatsDeserializeOwned,
158:         U: TryFrom<T>,
159:         U::Error: std::fmt::Display,
160:     {
161:         self.query_sats(sql)
162:             .await?
163:             .into_iter()
164:             .map(|row| {
165:                 U::try_from(row).map_err(|error| {
166:                     SpacetimeError::Spacetime(format!(
167:                         "generated-row presentation conversion failed: {error}"
168:                     ))
169:                 })
170:             })
171:             .collect()
172:     }

