1715: pub(crate) fn consume_party_currency(
1716:     ctx: &ReducerContext,
1717:     party_id: &str,
1718:     amount: u64,
1719: ) -> Result<(), String> {
1720:     let mut stacks: Vec<_> = ctx
1721:         .db
1722:         .party_inventory_item()
1723:         .party_id()
1724:         .filter(party_id)
1725:         .filter(|stack| crate::item::is_currency(ctx, &stack.item_id))
1726:         .collect();
1727:     if stacks
1728:         .iter()
1729:         .map(|stack| u64::from(stack.quantity))
1730:         .sum::<u64>()
1731:         < amount
1732:     {
1733:         return Err("Not enough party coin to cover this payment".into());
1734:     }
1735:     stacks.sort_by(|a, b| (&a.item_id, a.id).cmp(&(&b.item_id, b.id)));
1736:     let mut remaining = amount;
1737:     for mut stack in stacks {
1738:         let taken = remaining.min(u64::from(stack.quantity)) as u32;
1739:         stack.quantity -= taken;
1740:         remaining -= u64::from(taken);
1741:         if stack.quantity == 0 {
1742:             ctx.db.party_inventory_item().id().delete(stack.id);
1743:         } else {
1744:             ctx.db.party_inventory_item().id().update(stack);
1745:         }
1746:         if remaining == 0 {
1747:             break;
1748:         }
1749:     }
1750:     Ok(())
1751: }
