73: /// Movement's additive contribution to tactical exhaustion. A full jog is
74: /// explicitly capped at neutral, while partial jog input and walking recover
75: /// exhaustion and sprinting accumulates it. Other exhaustion sources can add
76: /// their own rates without being cleared by the selected movement pace.
77: pub fn tactical_movement_exhaustion_change_per_second(
78:     movement: Option<Vec2>,
79:     pace: MovementPace,
80:     weapon_guard: WeaponGuardState,
81:     body: crate::animation::BodyState,
82:     endurance: f32,
83:     sprint_speed: NonnegativeSpeed,
84: ) -> SpeedResult<f32> {
85:     let jog_speed = tactical_jog_speed(endurance)?;
86:     let effort_speed = if body == crate::animation::BodyState::Prone {
87:         tactical_prone_movement_speed_for_pace(movement, pace, jog_speed)?
88:             .checked_scale(TACTICAL_PRONE_EFFORT_SCALE)?
89:     } else {
90:         tactical_movement_speed_for_pace(movement, pace, weapon_guard, jog_speed, sprint_speed)?
91:     };
92:     let change = tactical_exhaustion_change_per_second(effort_speed, endurance)?;
93:     if pace == MovementPace::Jog {
94:         Ok(change.min(0.0))
95:     } else {
96:         Ok(change)
97:     }
98: }
