100: pub fn tactical_sprint_speed(
101:     left_leg_strength: f32,
102:     right_leg_strength: f32,
103:     left_leg_health: f32,
104:     right_leg_health: f32,
105:     burden_kg: f32,
106: ) -> SpeedResult<NonnegativeSpeed> {
107:     let effective_strength = ((left_leg_strength * left_leg_health.max(0.0)
108:         + right_leg_strength * right_leg_health.max(0.0))
109:         * 0.5)
110:         .max(0.0);
111:     let strength_ratio = effective_strength / REFERENCE_LEG_STRENGTH;
112:     let burden_ratio = REFERENCE_BURDEN_KG / burden_kg.max(1.0);
113:     let strength_speed = (REFERENCE_SPRINT_SPEED_METRES_PER_SECOND.metres_per_second()
114:         - SPRINT_CURVE_BASE_SPEED_METRES_PER_SECOND.metres_per_second())
115:         * strength_ratio;
116:     NonnegativeSpeed::from_metres_per_second(
117:         (SPRINT_CURVE_BASE_SPEED_METRES_PER_SECOND.metres_per_second()
118:             + strength_speed * burden_ratio.sqrt())
119:         .clamp(
120:             TACTICAL_WALK_SPEED_METRES_PER_SECOND.metres_per_second(),
121:             ELITE_SPRINT_SPEED_METRES_PER_SECOND.metres_per_second(),
122:         ),
123:     )
124: }
