272: pub(crate) fn apply_transient_attack_result(
273:     attacker_state: &mut TacticalCombatState,
274:     defender_limbs: &mut Limbs,
275:     defender_state: &mut TacticalCombatState,
276:     defender_wounds: &mut Vec<CombatWound>,
277:     result: AttackResult,
278:     body_part: BodyPart,
279: ) -> Option<(f32, f32)> {
280:     match result {
281:         AttackResult::ToAttacker { balance_damage, .. } => {
282:             attacker_state.imbalance += balance_damage.max(0.0);
283:             None
284:         }
285:         AttackResult::ToDefender {
286:             balance_damage,
287:             blunt_damage,
288:             ..
289:         } => {
290:             defender_state.imbalance += balance_damage.max(0.0);
291:             let damage = health_damage_from_attack(result, body_part);
292:             let applied = apply_clamped_limb_damage(defender_limbs.health_mut(body_part), damage);
293:             defender_state.acute_trauma += acute_trauma_incapacitation(body_part, applied);
294:             let (applied_cut, applied_blunt) = apportion_attack_health_damage(result, applied);
295:             defender_wounds.extend(wounds_from_applied_health_damage(
296:                 body_part,
297:                 applied_cut,
298:                 applied_blunt,
299:                 blunt_damage,
300:             ));
301:             if applied > 0.0 && applied_cut + applied_blunt > 0.0 {
302:                 Some((applied_cut, applied_blunt))
303:             } else {
304:                 None
305:             }
306:         }
307:     }
