21: #[must_use]
22: pub fn advance_combat_bleeding(
23:     blood_loss_fraction: f32,
24:     wounds: &[CombatWound],
25:     seconds: AnimationElapsed,
26: ) -> f32 {
27:     let flow = wounds
28:         .iter()
29:         .map(|wound| wound.blood_fraction_per_second.max(0.0))
30:         .sum::<f32>();
31:     (blood_loss_fraction + flow * seconds.seconds().max(0.0)).clamp(0.0, 1.0)
