34: #[must_use]
35: pub fn wounds_from_applied_health_damage(
36:     part: BodyPart,
37:     applied_cut: f32,
38:     applied_blunt: f32,
39:     blunt_energy_joules: f32,
40: ) -> Vec<CombatWound> {
41:     let blunt_coefficient = match part {
42:         BodyPart::Head => 0.015,
43:         BodyPart::Stomach => 0.01,
44:         BodyPart::Chest => 0.0075,
45:         BodyPart::LeftArm | BodyPart::RightArm | BodyPart::LeftLeg | BodyPart::RightLeg => 0.005,
46:     };
47:     let open_flow = applied_cut.max(0.0) * 0.5 / 60.0;
48:     let internal_bleeding_threshold_joules = match part {
49:         BodyPart::Head => 4.0,
50:         BodyPart::Chest | BodyPart::Stomach => 8.0,
51:         BodyPart::LeftArm | BodyPart::RightArm | BodyPart::LeftLeg | BodyPart::RightLeg => 6.0,
52:     };
53:     let internal_flow = if blunt_energy_joules >= internal_bleeding_threshold_joules {
54:         applied_blunt.max(0.0) * blunt_coefficient / 60.0
55:     } else {
56:         0.0
57:     };
58:     [
59:         (CombatWoundKind::Open, open_flow),
60:         (CombatWoundKind::Internal, internal_flow),
61:     ]
62:     .into_iter()
63:     .filter_map(|(kind, blood_fraction_per_second)| {
64:         (blood_fraction_per_second > 0.0).then_some(CombatWound {
65:             body_part: part,
66:             kind,
67:             blood_fraction_per_second,
68:         })
69:     })
