220: impl GuideMap {
221:     pub fn new(strands: &Strands, distance: f32, mask: f32, seed: u32) -> Self {
222:         let n = strands.len();
223:         if distance <= 0.0 || n == 0 {
224:             return Self {
225:                 guide: (0..n as u32).collect(),
226:                 guides: (0..n as u32).collect(),
227:             };
228:         }
229:         // Candidates in a random order; each kept with probability `mask`.
230:         let mut order: Vec<u32> = (0..n as u32).collect();
231:         order.sort_by_key(|&s| rng::hash(strands.id[s as usize].word(), seed));
232:         let mut grid = PointGrid::new(distance);
233:         let mut guides = Vec::new();
234:         for &s in &order {
235:             if rng::unit(strands.id[s as usize].word(), seed ^ 0x2F0B_1A3D) >= mask {
236:                 continue;
237:             }
238:             let root = strands.root(s as usize);
239:             let group = strands.group[s as usize];
240:             if !grid.any_within(root, distance, |g| g == group) {
241:                 grid.insert(root, group);
242:                 guides.push(s);
243:             }
244:         }
245:         if guides.is_empty() {
246:             let s = order[0];
247:             grid.insert(strands.root(s as usize), strands.group[s as usize]);
248:             guides.push(s);
249:         }
250:         let guide = (0..n)
251:             .into_par_iter()
252:             .map(|s| {
253:                 let root = strands.root(s);
254:                 let group = strands.group[s];
255:                 let nearest = grid
256:                     .nearest(root, distance * 8.0, |g| g == group)
257:                     .or_else(|| grid.nearest(root, f32::INFINITY, |_| true));
258:                 nearest.map_or(s as u32, |(i, _)| guides[i as usize])
259:             })
260:             .collect();
261:         Self { guide, guides }
262:     }

