1: //! Read-only ZIP storage with application-owned member selection and decoding.
2: //!
3: //! `rawzip` owns directory, ZIP64 and member framing. Stored members borrow the
4: //! mapped or owned archive bytes; `flate2` decodes Deflate members into owned data.
5: 
6: use std::borrow::Cow;
7: use std::io::Read;
8: use std::path::Path;
9: 
10: use flate2::read::DeflateDecoder;
11: use memmap2::Mmap;
12: use rawzip::{ZipArchiveEntryWayfinder, ZipLocator, ZipSliceArchive};
13: 
14: pub use compression::ZipCompressionCode;
15: pub use error::{Result, ZipFileOperation, ZipReadError};
16: pub use extent::DeclaredUncompressedByteLength;
17: 
18: use compression::ZipCompression;
19: use member_count::ArchiveMemberCount;
20: pub use names::ArchiveMemberName;
21: 
22: mod compression;
23: mod error;
24: mod extent;
25: mod member_count;
26: mod names;
27: 
28: // Application selection policy, measured in archive bytes from the end.
29: const END_DIRECTORY_SEARCH_WINDOW_BYTES: u64 = 66_000;
30: 
31: struct Entry {
32:     name: ArchiveMemberName,
33:     compression: ZipCompression,
34:     uncompressed_size: DeclaredUncompressedByteLength,
35:     location: ZipArchiveEntryWayfinder,
36: }
37: 
38: /// A ZIP archive backed by a read-only mapping or an owned byte buffer.
39: pub struct ZipArchive {
40:     archive: ZipSliceArchive<ArchiveData>,
41:     entries: Vec<Entry>,
42: }
43: 
44: /// A member selected from, and inseparable from, its owning archive.
45: pub(crate) struct ZipMember<'archive> {
46:     archive: &'archive ZipArchive,
47:     entry: &'archive Entry,
48: }
49: 
50: enum ArchiveData {
51:     Mapped(Mmap),
52:     Owned(Vec<u8>),
53: }
54: 
55: impl AsRef<[u8]> for ArchiveData {
56:     fn as_ref(&self) -> &[u8] {
57:         match self {
58:             Self::Mapped(data) => data,
59:             Self::Owned(data) => data,
60:         }
61:     }
62: }
63: 
64: impl ZipArchive {
65:     pub fn open(path: impl AsRef<Path>) -> Result<Self> {
66:         let path = path.as_ref();
67:         let file = std::fs::File::open(path).map_err(|source| ZipReadError::Native {
68:             operation: ZipFileOperation::Open,
69:             native_path: path.to_path_buf(),
70:             source,
71:         })?;
72:         // SAFETY: model assets are read-only inputs; concurrent truncation by
73:         // another process is out of scope, as elsewhere in this workspace.
74:         let data = unsafe { Mmap::map(&file) }.map_err(|source| ZipReadError::Native {
75:             operation: ZipFileOperation::Map,
76:             native_path: path.to_path_buf(),
77:             source,
78:         })?;
79:         Self::from_data(ArchiveData::Mapped(data))
80:     }
81: 
82:     pub fn from_bytes(data: Vec<u8>) -> Result<Self> {
83:         Self::from_data(ArchiveData::Owned(data))
84:     }
85: 
86:     fn from_data(data: ArchiveData) -> Result<Self> {
87:         let archive = ZipLocator::new()
88:             .max_search_space(END_DIRECTORY_SEARCH_WINDOW_BYTES)
89:             .locate_in_slice(data)
90:             .map_err(|(_, source)| ZipReadError::from(source))?;
91:         let member_count = ArchiveMemberCount::from(archive.entries_hint());
92:         let mut entries = Vec::with_capacity(member_count.initial_capacity());
93:         let mut directory = archive.entries();
94:         // The declaration remains our upper bound; rawzip bounds each record
95:         // by the selected directory span. No partial archive is published on error.
96:         for _ in member_count.native_iteration_range() {
97:             let Some(header) = directory.next_entry().map_err(ZipReadError::from)? else {
98:                 break;
99:             };
100:             entries.push(Entry {
101:                 name: ArchiveMemberName::from(header.file_path().as_ref()),
102:                 compression: ZipCompression::from(header.compression_method()),
103:                 uncompressed_size: DeclaredUncompressedByteLength::from_bytes(
104:                     header.uncompressed_size_hint(),
105:                 ),
106:                 location: header.wayfinder(),
107:             });
108:         }
109:         Ok(Self { archive, entries })
110:     }
111: 
112:     /// Member names, in central-directory order.
113:     pub fn names(&self) -> impl Iterator<Item = &ArchiveMemberName> {
114:         self.entries.iter().map(|entry| &entry.name)
115:     }
116: 
117:     pub fn contains(&self, name: &ArchiveMemberName) -> bool {
118:         self.entries.iter().any(|entry| entry.name == *name)
119:     }
120: 
121:     /// Declared decoded length of the first exact match, without verification.
122:     pub fn uncompressed_size(
123:         &self,
124:         name: &ArchiveMemberName,
125:     ) -> Option<DeclaredUncompressedByteLength> {
126:         self.find(|member| member == name)
127:             .map(|member| member.uncompressed_size())
128:     }
129: 
130:     pub(crate) fn find(
131:         &self,
132:         predicate: impl Fn(&ArchiveMemberName) -> bool,
133:     ) -> Option<ZipMember<'_>> {
134:         self.entries
135:             .iter()
136:             .find(|entry| predicate(&entry.name))
137:             .map(|entry| ZipMember {
138:                 archive: self,
139:                 entry,
140:             })
141:     }
142: 
143:     /// Decodes one member. Stored members borrow from the archive buffer.
144:     pub fn bytes(&self, name: &ArchiveMemberName) -> Result<Cow<'_, [u8]>> {
145:         self.find(|member| member == name)
146:             .ok_or_else(|| ZipReadError::MissingMember { name: name.clone() })?
147:             .bytes()
148:     }
149: }
150: 
151: impl<'archive> ZipMember<'archive> {
152:     pub(crate) fn name(&self) -> &ArchiveMemberName {
153:         &self.entry.name
154:     }
155: 
156:     pub(crate) fn uncompressed_size(&self) -> DeclaredUncompressedByteLength {
157:         self.entry.uncompressed_size
158:     }
159: 
160:     pub(crate) fn bytes(&self) -> Result<Cow<'archive, [u8]>> {
161:         let entry = self.entry;
162:         let member = self
163:             .archive
164:             .archive
165:             .get_entry(entry.location)
166:             .map_err(|source| ZipReadError::member(entry.name.clone(), source))?;
167:         let raw = member.data();
168:         match entry.compression {
169:             ZipCompression::Stored => Ok(Cow::Borrowed(raw)),
170:             ZipCompression::Deflated => {
171:                 let mut out =
172:                     Vec::with_capacity(entry.uncompressed_size.native_allocation_capacity());
173:                 DeflateDecoder::new(raw)
174:                     .read_to_end(&mut out)
175:                     .map_err(|source| ZipReadError::Inflate {
176:                         name: entry.name.clone(),
177:                         source,
178:                     })?;
179:                 Ok(Cow::Owned(out))
180:             }
181:             ZipCompression::Unsupported(code) => Err(ZipReadError::UnsupportedCompression { code }),
182:         }
183:     }
184: }

