1: //! MHR's corrective archive schema and its fixed array roles.
2: 
3: use std::path::Path;
4: 
5: use anyhow::{Context, Result};
6: use fabelgeist_numpy_storage::{NpyArray, NpyFloat32Values, NpyIntegerValues, Npz, NpzArrayName};
7: 
8: use super::import::{CorrectiveLayout, SparseActivation};
9: 
10: /// Encoded corrective archives with explicit roles before NPZ admission.
11: /// Payload contents are checked when the archives and their members are read.
12: pub struct CorrectiveArchiveBytes {
13:     pub activation: Vec<u8>,
14:     pub basis: Vec<u8>,
15: }
16: 
17: pub(super) struct CorrectiveArchives {
18:     activation: Npz,
19:     basis: Npz,
20: }
21: 
22: pub(super) enum CorrectiveArray {
23:     Basis,
24:     SparseIndices,
25:     SparseWeights,
26: }
27: 
28: impl CorrectiveArray {
29:     pub(super) fn name(self) -> NpzArrayName {
30:         NpzArrayName::new(match self {
31:             Self::Basis => "corrective_blendshapes",
32:             Self::SparseIndices => "0.sparse_indices",
33:             Self::SparseWeights => "0.sparse_weight",
34:         })
35:     }
36: }
37: 
38: impl CorrectiveArchives {
39:     pub(super) fn open(activation: &Path, basis: &Path) -> Result<Self> {
40:         let basis = Npz::open(basis)?;
41:         let activation = Npz::open(activation)?;
42:         Ok(Self { activation, basis })
43:     }
44: 
45:     pub(super) fn from_bytes(archives: CorrectiveArchiveBytes) -> Result<Self> {
46:         let activation = Npz::from_bytes(archives.activation)?;
47:         let basis = Npz::from_bytes(archives.basis)?;
48:         Ok(Self { activation, basis })
49:     }
50: 
51:     pub(super) fn basis(&self) -> Result<Option<NpyArray>> {
52:         let name = CorrectiveArray::Basis.name();
53:         let Some(member) = self.basis.get(&name) else {
54:             return Ok(None);
55:         };
56:         member
57:             .array()
58:             .context("reading the corrective basis")
59:             .map(Some)
60:     }
61: 
62:     pub(super) fn activation<'layout>(
63:         &self,
64:         layout: &'layout CorrectiveLayout,
65:     ) -> Result<SparseActivation<'layout>> {
66:         let indices = NpyIntegerValues::from(
67:             &self
68:                 .activation
69:                 .array(&CorrectiveArray::SparseIndices.name())
70:                 .context("reading the sparse activation indices")?,
71:         );
72:         let weights = NpyFloat32Values::from(
73:             &self
74:                 .activation
75:                 .array(&CorrectiveArray::SparseWeights.name())
76:                 .context("reading the sparse activation weights")?,
77:         );
78:         Ok(SparseActivation::new(indices, weights, layout)?)
79:     }
80: }

