239:     pair: Pair,
240:     positions: &mut [Vec3],
241:     previous: &[Vec3],
242:     masses: &[ParticleInverseMass],
243:     ids: [usize; 4],
244:     thickness: f32,
245:     velocities: Option<&mut [Vec3]>,
246: ) -> usize {
247:     let start = ids.map(|i| previous[i]);
248:     let end = ids.map(|i| positions[i]);
249:     // The CCD guard is inside the resting contact shell. This lets touching
250:     // cloth slide tangentially without returning time zero on every step.
251:     let contact = ccd::sweep(pair, start, end, thickness * 0.5)
252:         .unwrap_or_else(|| ccd::proximity(pair, end, start));
253:     debug_assert!((0.0..=1.0).contains(&contact.time));
254:     let separation = ids
255:         .iter()
256:         .zip(contact.weights)
257:         .fold(
258:             Vec3::default(),
259:             |sum: Vec3, (&i, w): (&usize, ConstraintGradient)| -> Vec3 {
260:                 sum + w.contribution(positions[i])
261:             },
262:         )
263:         .dot(contact.normal);
264:     let depth = ProjectionDepth::from(thickness - separation);
265:     if depth.activity() == ProjectionActivity::Inactive {
266:         return 0;
267:     }
268:     let denominator: EffectiveInverseMass = ids
269:         .iter()
270:         .zip(contact.weights)
271:         .map(
272:             |(&i, w): (&usize, ConstraintGradient)| -> EffectiveInverseMass {
273:                 w.inverse_response(masses[i])
274:             },
275:         )
276:         .sum();
277:     if denominator.contact_activity() == ProjectionActivity::Inactive {
278:         return 0;
279:     }
280:     if let Some(velocities) = velocities {
281:         let relative = RelativeNormalSpeed::from(
282:             ids.iter()
283:                 .zip(contact.weights)
284:                 .fold(
285:                     Vec3::default(),
286:                     |sum: Vec3, (&i, w): (&usize, ConstraintGradient)| -> Vec3 {
287:                         sum + w.contribution(velocities[i])
288:                     },
289:                 )
290:                 .dot(contact.normal),
291:         );
292:         if relative.activity() == ProjectionActivity::Active {
293:             for (i, w) in ids.into_iter().zip(contact.weights) {
294:                 velocities[i] -= relative
295:                     .contact_correction(w, masses[i], denominator)
296:                     .along(contact.normal);
297:             }
