1: //! Greedy constraint coloring preserves arrival order within each color.
2: //!
3: //! Constraints sharing a particle occupy different dispatches. Sequential color
4: //! dispatches retain the solver's Gauss-Seidel order without device races.
5: use std::collections::HashMap;
