14: 
15: /// Number of colors in the sequential solve schedule.
16: #[derive(Clone, Copy, Debug, Display, From, PartialEq, Eq, PartialOrd, Ord)]
17: pub struct ColorCount(usize);
18: 
19: /// A constraint address after permutation into color order.
20: ///
21: /// ```compile_fail
22: /// use fabelgeist_xpbd::{ConstraintIndex, ConstraintSlot};
23: /// fn original(_: ConstraintIndex) {}
24: /// fn wrong(slot: ConstraintSlot) { original(slot); }
25: /// ```
26: #[derive(Clone, Copy, Debug, PartialEq, Eq)]
27: pub struct ConstraintSlot(u32);
28: 
29: /// Immutable color interval, in reordered constraint slots.
30: #[derive(Clone, Copy, Debug, PartialEq, Eq)]
31: pub struct ColorRange {
32:     color: ConstraintColor,
33:     first: ConstraintSlot,
34:     end: ConstraintSlot,
35: }
36: 
37: /// Constraints grouped into colors, with their immutable permutation.
38: #[derive(Clone, Debug, Default)]
39: pub struct Coloring {
40:     order: Vec<ConstraintIndex>,
41:     ranges: Vec<ConstraintSlot>,
42: }
43: 
44: impl From<ConstraintSlot> for usize {
45:     fn from(slot: ConstraintSlot) -> Self {
46:         slot.0 as usize
47:     }
48: }
49: 
50: impl ColorRange {
51:     pub fn color(self) -> ConstraintColor {
52:         self.color
53:     }
54:     pub fn count(self) -> ConstraintCount {
55:         ((self.end.0 - self.first.0) as usize).into()
56:     }
57:     pub fn slots(self) -> impl Iterator<Item = ConstraintSlot> {
58:         (self.first.0..self.end.0).map(ConstraintSlot)
59:     }
60:     pub(crate) fn bind(self, parameters: &mut PassParameters) {
61:         parameters.insert("first", self.first.0);
62:         parameters.insert("count", self.count().uniform());
63:     }
64:     pub(crate) fn dispatch_items(self) -> u32 {
65:         self.count().dispatch_items()
66:     }
67: }
