69: impl Coloring {
70:     pub fn color_count(&self) -> ColorCount {
71:         self.ranges.len().saturating_sub(1).into()
72:     }
73:     pub fn constraint_count(&self) -> ConstraintCount {
74:         self.order.len().into()
75:     }
76:     pub fn order(&self) -> &[ConstraintIndex] {
77:         &self.order
78:     }
79:     pub fn colors(&self) -> impl Iterator<Item = ColorRange> + '_ {
80:         self.ranges
81:             .windows(2)
82:             .enumerate()
83:             .map(|(color, bounds)| ColorRange {
84:                 color: ConstraintColor(color),
85:                 first: bounds[0],
86:                 end: bounds[1],
87:             })
88:     }
89:     pub fn for_incidence(incidence: &ConstraintIncidence<'_>) -> Self {
90:         let records: Vec<&[ParticleIndex]> = incidence.records().collect();
