170: /// Distance constraints: the workhorse. Cloth stretch, seams and tethers are
171: /// all this kernel with different rest lengths and compliances.
172: pub const DISTANCE: &str = r#"
173: @group(0) @binding(1) var<storage, read_write> lambdas: array<f32>;
174: // Two particle indices per constraint.
175: @group(0) @binding(2) var<storage, read> particles: array<u32>;
176: @group(0) @binding(3) var<storage, read> rest_lengths: array<f32>;
177: @group(0) @binding(4) var<uniform> params: SolveParams;
