179: @compute @workgroup_size(256)
180: fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {
181:     let local = global_id.x;
182:     if (local >= params.count) {
183:         return;
184:     }
185:     let constraint = params.first + local;
186: 
187:     let a = particles[constraint * 2u];
188:     let b = particles[constraint * 2u + 1u];
189:     let inverse_mass_a = particle_inverse_mass(a);
190:     let inverse_mass_b = particle_inverse_mass(b);
191: 
192:     let delta = particle_position(a) - particle_position(b);
193:     let distance = length(delta);
194:     // Two coincident particles have no direction to separate along. Leaving
195:     // them alone lets the next substep, when something else has nudged them
196:     // apart, do the work.
197:     if (distance < 1e-9) {
198:         return;
199:     }
200: 
201:     let normal = delta / distance;
202:     let value = distance - rest_lengths[constraint];
203:     // |grad| is 1 for both particles, so the weighted denominator is just the
204:     // sum of the inverse masses.
205:     let alpha_tilde = xpbd_alpha_tilde(params.compliance, params.substep);
206:     let solved = xpbd_solve(value, inverse_mass_a + inverse_mass_b, lambdas[constraint], alpha_tilde);
207:     if (!solved.valid) {
208:         return;
209:     }
210: 
211:     lambdas[constraint] = lambdas[constraint] + solved.delta_lambda;
212:     particle_move(a, normal * (inverse_mass_a * solved.delta_lambda));
213:     particle_move(b, normal * (-inverse_mass_b * solved.delta_lambda));
214: }
