29: /// How the substep loop is driven.
30: #[derive(Clone, Copy, Debug)]
31: pub struct SolverSettings {
32:     /// Substeps per call to [`Solver::step`]. More is stiffer and steadier;
33:     /// the cost is linear.
34:     pub substeps: u32,
35:     /// Constraint sweeps within each substep. XPBD wants one; more helps a
36:     /// badly conditioned set converge, at the price of the compliance meaning
37:     /// slightly less than it says.
38:     pub iterations: u32,
39:     pub gravity: Vec3,
40:     /// Exponential velocity drag, per second. Independent of the substep
41:     /// count, so changing `substeps` does not change how draggy the cloth is.
42:     pub damping: f32,
43:     /// Ceiling on particle speed. It only ever binds when something has
44:     /// already gone wrong, and it is what turns a blown-up frame into a
45:     /// recoverable one rather than a garment flung off the screen.
46:     pub max_speed: f32,
47: }
48: 
49: impl Default for SolverSettings {
50:     fn default() -> Self {
51:         Self {
52:             substeps: 10,
53:             iterations: 1,
54:             // Metres per second squared, and the rest of the stack is in
55:             // metres, so a garment in centimetres has to be scaled on the way
56:             // in.
57:             gravity: Vec3::new(0.0, -9.81, 0.0),
58:             damping: 0.1,
59:             max_speed: 20.0,
