40: #[derive(Clone, Debug, Default)]
41: pub struct Bvh {
42:     pub nodes: Vec<Node>,
43:     /// Primitive indices, permuted so that a leaf's primitives are contiguous.
44:     pub indices: Vec<u32>,
45: }
46: 
47: impl Bvh {
48:     /// Build over primitive bounding boxes. The order of `bounds` is the
49:     /// primitive numbering every query reports back.
50:     pub fn build(bounds: &[Aabb]) -> Self {
51:         let mut bvh = Self {
52:             nodes: Vec::new(),
53:             indices: (0..bounds.len() as u32).collect(),
54:         };
55:         if bounds.is_empty() {
56:             return bvh;
57:         }
58: 
59:         // An upper bound: a binary tree over n leaves of at least one
60:         // primitive each has at most 2n - 1 nodes.
61:         bvh.nodes.reserve(2 * bounds.len());
62:         bvh.nodes.push(Node {
63:             bounds: Aabb::EMPTY,
64:             left_first: 0,
65:             count: bounds.len() as u32,
66:         });
67:         bvh.subdivide(0, bounds);
68:         bvh
69:     }
70: 
71:     pub fn is_empty(&self) -> bool {
72:         self.nodes.is_empty()
73:     }
74: 
75:     pub fn primitive_count(&self) -> usize {
76:         self.indices.len()
77:     }
78: 
79:     pub fn bounds(&self) -> Aabb {
80:         self.nodes.first().map(|n| n.bounds).unwrap_or(Aabb::EMPTY)
81:     }
82: 
83:     fn subdivide(&mut self, node_index: usize, bounds: &[Aabb]) {
84:         let (first, count) = {
85:             let node = &self.nodes[node_index];
86:             (node.left_first as usize, node.count as usize)
87:         };
88:         let slice = &self.indices[first..first + count];
89: 
90:         let node_bounds = slice
91:             .iter()
92:             .fold(Aabb::EMPTY, |acc, &i| acc.union(bounds[i as usize]));
93:         self.nodes[node_index].bounds = node_bounds;
94: 
95:         if count <= MAX_LEAF_SIZE {
96:             return;
97:         }
98: 
99:         let Some(split) = self.find_split(first, count, bounds) else {
100:             return;
101:         };
102: 
103:         // Partition in place around the chosen plane.
104:         let (axis, position) = split;
105:         let mut left = first;
106:         let mut right = first + count;
107:         while left < right {
108:             let centroid = bounds[self.indices[left] as usize].center().axis(axis);
109:             if centroid < position {
110:                 left += 1;
111:             } else {
112:                 right -= 1;
113:                 self.indices.swap(left, right);
114:             }
115:         }
116: 
117:         let left_count = left - first;
118:         // Every centroid landing on one side means the split bought nothing;
119:         // stop rather than recurse forever on the same set.
120:         if left_count == 0 || left_count == count {
121:             return;
122:         }
123: 
124:         let left_child = self.nodes.len() as u32;
125:         self.nodes.push(Node {
126:             bounds: Aabb::EMPTY,
127:             left_first: first as u32,
128:             count: left_count as u32,
129:         });
130:         self.nodes.push(Node {
131:             bounds: Aabb::EMPTY,
132:             left_first: left as u32,
133:             count: (count - left_count) as u32,
