13: // Leave headroom for subsequent body and self-contact corrections.
14: const PROJECTION_TOLERANCE: f32 = CLEARANCE_TOLERANCE * 0.1;
15: 
16: impl OuterLayer {
17:     /// Maximum normal-clearance deficit anywhere on the cloth triangles.
18:     /// Checking only particle positions would miss a plate wholly inside a face.
19:     pub fn surface_residual(&self, positions: &[Vec3], faces: &[[u32; 3]]) -> f32 {
20:         let mut residual = self.residual(positions);
21:         for face in faces {
22:             let points = face.map(|i| positions[i as usize]);
23:             for index in self.overlaps(points) {
24:                 let (a, b, c) = self.surface.triangle(index);
25:                 let raw = (b - a).cross(c - a);
26:                 if raw.length() <= 1e-10 {
27:                     continue;
28:                 }
29:                 let normal = raw / raw.length();
30:                 let alignment = normal.dot(self.inward);
31:                 if alignment <= 1e-5 {
32:                     continue;
33:                 }
34:                 for ClippedSample { point, .. } in clipped(points, [a, b, c], self.inward) {
35:                     residual = residual.max(self.clearance - (point - a).dot(normal));
36:                 }
37:             }
38:         }
39:         residual
40:     }
41: 
42:     /// Constrain triangle interiors as well as vertices. In the layer's view,
43:     /// signed separation is linear over each overlap polygon, so its vertices
44:     /// include every possible minimum (including a plate edge through cloth).
45:     pub(super) fn project_surface(
46:         &self,
47:         positions: &mut [Vec3],
48:         velocities: &mut [Vec3],
49:         masses: &[ParticleInverseMass],
50:         faces: &[[u32; 3]],
51:     ) -> bool {
52:         let mut changed = false;
53:         for &face in faces {
54:             let points = face.map(|i| positions[i as usize]);
55:             let candidates = self.overlaps(points);
56:             for index in candidates {
57:                 let points = face.map(|i| positions[i as usize]);
58:                 let (a, b, c) = self.surface.triangle(index);
59:                 let raw = (b - a).cross(c - a);
60:                 if raw.length() <= 1e-10 {
61:                     continue;
62:                 }
63:                 let normal = raw / raw.length();
64:                 let alignment = normal.dot(self.inward);
65:                 if alignment <= 1e-5 {
66:                     continue;
67:                 }
68:                 for ClippedSample { weights, .. } in clipped(points, [a, b, c], self.inward) {
69:                     let point = (0..3).fold(Vec3::default(), |p: Vec3, i: usize| -> Vec3 {
70:                         p + weights[i].contribution(positions[face[i] as usize])
71:                     });
72:                     let depth = self.clearance - (point - a).dot(normal);
73:                     if depth <= PROJECTION_TOLERANCE {
74:                         continue;
75:                     }
76:                     let denominator: EffectiveInverseMass = (0..3)
77:                         .map(|i: usize| -> EffectiveInverseMass {
78:                             weights[i].inverse_response(masses[face[i] as usize])
79:                         })
80:                         .sum();
81:                     if denominator.layer_activity() == ProjectionActivity::Inactive {
82:                         continue;
83:                     }
84:                     let incoming = (0..3)
85:                         .map(|i: usize| -> IncomingNormalSpeed {
86:                             weights[i].weighted_normal_speed(velocities[face[i] as usize], normal)
87:                         })
88:                         .sum::<IncomingNormalSpeed>()
89:                         .incoming();
90:                     for i in 0..3 {
91:                         let vertex = face[i] as usize;
92:                         let share = weights[i].mass_share(masses[vertex], denominator);
93:                         positions[vertex] += share
94:                             .position_correction(ProjectionDepth::from(depth))
95:                             .along(normal);
96:                         velocities[vertex] -= share.speed_correction(incoming).along(normal);
97:                     }
98:                     changed = true;
99:                 }
100:             }
101:         }
102:         changed
103:     }
104: 
105:     fn overlaps(&self, points: [Vec3; 3]) -> Vec<u32> {
106:         let bounds = self.surface.bvh.bounds();
107:         let reach = (points[0] - bounds.center()).length() + bounds.extent().length();
108:         let query = fabelgeist_bvh::Aabb::from_points(
109:             points
110:                 .into_iter()
111:                 .flat_map(|p| [p - self.inward * reach, p + self.inward * reach]),
112:         );
113:         let mut candidates = Vec::new();
114:         self.surface
115:             .bvh
116:             .candidates_aabb(&query, |i| candidates.push(i));
117:         candidates
118:     }
119: }
