96: /// Which cell each particle is in, hashed into a fixed table.
97: pub const HASH: &str = r#"
98: @group(0) @binding(0) var<storage, read> positions: array<vec4<f32>>;
99: @group(0) @binding(1) var<storage, read_write> cells: array<u32>;
100: @group(0) @binding(2) var<storage, read_write> indices: array<u32>;
101: 
102: struct HashParams {
103:     count: u32,
104:     table_size: u32,
105:     inverse_spacing: f32,
106:     pad: u32,
107: };
108: @group(0) @binding(3) var<uniform> params: HashParams;
109: 
110: fn cell_of(position: vec3<f32>, inverse_spacing: f32) -> vec3<i32> {
111:     return vec3<i32>(floor(position * inverse_spacing));
112: }
113: 
114: fn hash_cell(cell: vec3<i32>, table_size: u32) -> u32 {
115:     // Three large odd primes: the usual spatial hash, and good enough that
116:     // collisions are rare and harmless when they happen (a collision just
117:     // means two distant cells share a bucket, and the exact distance test
118:     // rejects the false neighbours).
119:     let h = (u32(cell.x) * 73856093u) ^ (u32(cell.y) * 19349663u) ^ (u32(cell.z) * 83492791u);
120:     return h % table_size;
121: }
