123: @compute @workgroup_size(256)
124: fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {
125:     let index = global_id.x;
126:     if (index >= params.count) {
127:         return;
128:     }
129:     cells[index] = hash_cell(
130:         cell_of(positions[index].xyz, params.inverse_spacing),
131:         params.table_size,
132:     );
133:     indices[index] = index;
134: }
