492: /// `Edge.assembly` -- endpoints plus curvature/label properties.
493: fn assembly_edge(edge: &super::edge::EdgeRef) -> ([V2; 2], EdgeSpec) {
494:     let e = edge.borrow();
495:     let mut spec = EdgeSpec {
496:         endpoints: [0, 1],
497:         label: if e.label.is_empty() {
498:             None
499:         } else {
500:             Some(e.label.clone())
501:         },
502:         curvature: None,
503:     };
504: 
505:     match &e.kind {
506:         EdgeKind::Line => {}
507:         EdgeKind::Circle { .. } => {
508:             let (rad, large_arc, right) = e.as_radius_flag();
509:             spec.curvature = Some(crate::pattern::spec::Curvature::Circle {
510:                 radius: rad,
511:                 large_arc,
512:                 right,
513:             });
514:         }
515:         EdgeKind::Curve { control_points } => {
516:             spec.curvature = Some(if control_points.len() == 1 {
517:                 crate::pattern::spec::Curvature::Quadratic {
518:                     params: control_points.clone(),
519:                 }
520:             } else {
521:                 crate::pattern::spec::Curvature::Cubic {
522:                     params: control_points.clone(),
523:                 }
524:             });
525:         }
526:     }
527: 
528:     ([e.start_p(), e.end_p()], spec)
529: }
