1: //! A sewn garment's pattern, in GarmentCode's vocabulary.
2: //!
3: //! A pattern chooses an upper-body block with its sleeves and collar, and a
4: //! lower garment. It is written over the reference T-shirt design, so these
5: //! choices are the whole difference between one garment and another. Value
6: //! ranges follow the GarmentCodeData design space.
7: use super::*;
8: use std::fmt::Debug;
9: use std::ops::RangeInclusive;
10: 
11: pub mod shapes;
12: 
13: /// Waistband circumference over the waist measurement, for lower garments
14: /// worn without an upper.
15: const WAISTBAND_EASE: f64 = 1.03;
16: /// A fitted bodice always ends at the waist, one neck-to-waist length down.
17: const WAIST_LENGTH: f64 = 1.0;
18: /// Hem depth, in neck-to-waist lengths, from which a straight body hangs across
19: /// both legs instead of following the torso.
20: const CROTCH_LENGTH: f64 = 1.8;
21: 
22: /// The upper-body block.
23: #[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq)]
24: #[serde(rename_all = "snake_case")]
25: pub enum Upper {
26:     /// The straight T-tunic block. `length` runs down from the shoulder in
27:     /// neck-to-waist lengths, `width` eases the bust and `flare` widens the
28:     /// hem against it.
29:     Straight { length: f64, width: f64, flare: f64 },
30:     /// The darted bodice, always cut at the waist.
31:     Fitted,
32: }
33: 
34: impl Upper {
35:     pub const LENGTH: RangeInclusive<f64> = 0.5..=3.5;
36:     pub const WIDTH: RangeInclusive<f64> = 1.0..=1.3;
37:     pub const FLARE: RangeInclusive<f64> = 0.7..=1.6;
38:     /// A plain shirt to just below the waist.
39:     pub const STRAIGHT: Self = Self::Straight {
40:         length: 1.2,
41:         width: 1.05,
42:         flare: 1.0,
43:     };
44: }
45: 
46: /// Sleeves: `length` as a fraction of the arm below the armhole, and
47: /// `cuff_width` as a fraction of the armhole span, never narrower than the
48: /// wrist.
49: #[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq)]
50: #[serde(deny_unknown_fields)]
51: pub struct Sleeves {
52:     pub length: f64,
53:     pub cuff_width: f64,
54: }
55: 
56: impl Sleeves {
57:     pub const LENGTH: RangeInclusive<f64> = 0.1..=1.15;
58:     pub const CUFF_WIDTH: RangeInclusive<f64> = 0.2..=2.0;
59:     /// Ends at the wrist on a straight body. The measured arm runs from the
60:     /// shoulder joint, so a whole arm's length of sleeve reaches onto the hand,
61:     /// and a cuff narrower than the hand is pierced by it.
62:     pub const TO_THE_WRIST: f64 = 0.9;
63:     /// Ends at the wrist on a fitted bodice, whose armhole sits further out.
64:     pub const FITTED_TO_THE_WRIST: f64 = 0.8;
65:     pub const SHORT: Self = Self {
66:         length: 0.3,
67:         cuff_width: 1.0,
68:     };
69: }
70: 
71: /// A standing band collar sewn onto the neckline.
72: #[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
73: #[serde(deny_unknown_fields)]
74: pub struct Collar {
75:     pub height_cm: i64,
76: }
77: 
78: impl Collar {
79:     pub const HEIGHT_CM: RangeInclusive<i64> = 2..=8;
80:     pub const STANDING: Self = Self { height_cm: 4 };
81: }
82: 
83: /// The lower-body garment.
84: #[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq)]
85: #[serde(rename_all = "snake_case")]
86: pub enum Lower {
87:     /// `length` as a fraction of the leg, `width` easing the crotch, and
88:     /// `flare` tapering or widening the hem.
89:     Trousers { length: f64, width: f64, flare: f64 },
90:     /// The two-panel skirt: `length` as a fraction of the leg and `flare_cm`
91:     /// added to each side of both hems.
92:     Skirt { length: f64, flare_cm: f64 },
93: }
94: 
95: impl Lower {
96:     pub const TROUSERS_LENGTH: RangeInclusive<f64> = 0.2..=0.9;
97:     pub const TROUSERS_WIDTH: RangeInclusive<f64> = 1.0..=1.5;
98:     /// A narrower leg slides down the wearer while settling.
99:     pub const TROUSERS_FLARE: RangeInclusive<f64> = 0.9..=1.2;
100:     pub const SKIRT_LENGTH: RangeInclusive<f64> = 0.1..=0.95;
101:     pub const SKIRT_FLARE_CM: RangeInclusive<f64> = 0.0..=20.0;
102:     /// Trouser length that ends at the ankle; longer legs reach over the foot.
103:     pub const TO_THE_ANKLE: f64 = 0.8;
104:     pub const TROUSERS: Self = Self::Trousers {
105:         length: Self::TO_THE_ANKLE,
106:         width: 1.0,
107:         flare: 1.0,
108:     };
109:     pub const SKIRT: Self = Self::Skirt {
110:         length: 0.45,
111:         flare_cm: 1.0,
112:     };
113: }
114: 
115: /// A sewn garment's pattern choices.
116: #[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq)]
117: #[serde(deny_unknown_fields)]
118: pub struct Pattern {
119:     pub upper: Option<Upper>,
120:     /// Only with an upper block.
121:     pub sleeves: Option<Sleeves>,
122:     /// Only with an upper block.
123:     pub collar: Option<Collar>,
124:     pub lower: Option<Lower>,
125: }
126: 
127: impl Default for Pattern {
128:     /// A short-sleeved shirt.
129:     fn default() -> Self {
130:         Self {
131:             upper: Some(Upper::STRAIGHT),
132:             sleeves: Some(Sleeves::SHORT),
133:             collar: None,
134:             lower: None,
135:         }
136:     }
137: }
138: 
139: fn within<T: PartialOrd + Debug>(what: &str, value: T, range: RangeInclusive<T>) -> Result<()> {
140:     if !range.contains(&value) {
141:         bail!("{what} {value:?} must be within {range:?}");
142:     }
143:     Ok(())
144: }
145: 
146: impl Pattern {
147:     /// How the sewn garment hangs, from what it covers.
148:     pub fn form(&self) -> GarmentForm {
149:         match (self.upper, self.lower) {
150:             (_, Some(Lower::Skirt { .. })) => GarmentForm::Skirted,
151:             (_, Some(Lower::Trousers { .. })) => GarmentForm::Legged,
152:             (Some(Upper::Straight { length, .. }), None) if length >= CROTCH_LENGTH => {
153:                 GarmentForm::Skirted
154:             }
155:             _ => GarmentForm::Upper,
156:         }
157:     }
158: 
159:     pub fn validate(&self) -> Result<()> {
160:         if self.upper.is_none() && self.lower.is_none() {
161:             bail!("a pattern needs an upper or a lower garment");
162:         }
163:         if self.upper.is_none() && (self.sleeves.is_some() || self.collar.is_some()) {
164:             bail!("sleeves and collars need an upper garment");
165:         }
166:         if let Some(Upper::Straight {
167:             length,
168:             width,
169:             flare,
170:         }) = self.upper
171:         {
172:             within("body length", length, Upper::LENGTH)?;
173:             within("body width", width, Upper::WIDTH)?;
174:             within("body flare", flare, Upper::FLARE)?;
175:         }
176:         if let Some(sleeves) = self.sleeves {
177:             within("sleeve length", sleeves.length, Sleeves::LENGTH)?;
178:             within("cuff width", sleeves.cuff_width, Sleeves::CUFF_WIDTH)?;
179:         }
180:         if let Some(collar) = self.collar {
181:             within("collar height", collar.height_cm, Collar::HEIGHT_CM)?;
182:         }
183:         match self.lower {
184:             Some(Lower::Trousers {
185:                 length,
186:                 width,
187:                 flare,
188:             }) => {
189:                 within("trouser length", length, Lower::TROUSERS_LENGTH)?;
190:                 within("trouser width", width, Lower::TROUSERS_WIDTH)?;
191:                 within("trouser flare", flare, Lower::TROUSERS_FLARE)?;
192:             }
193:             Some(Lower::Skirt { length, flare_cm }) => {
194:                 within("skirt length", length, Lower::SKIRT_LENGTH)?;
195:                 within("skirt flare", flare_cm, Lower::SKIRT_FLARE_CM)?;
196:             }
197:             None => {}
198:         }
199:         Ok(())
200:     }
201: 
