95: pub fn measured_body(input: &DrapeInput) -> Result<Body> {
96:     let joint = |name: &RigJointName| -> Result<[f32; 3]> {
97:         let i = name
98:             .index_in(&input.names)
99:             .with_context(|| format!("missing measurement joint {name}"))?;
100:         let j = input.joints.get(i).context("missing joint transform")?;
101:         Ok([j[0] * 100.0, j[1] * 100.0, j[2] * 100.0])
102:     };
103:     let marks = Landmarks {
104:         shoulders: [
105:             joint(&RigJointName::L_UPARM)?,
106:             joint(&RigJointName::R_UPARM)?,
107:         ],
108:         elbows: [
109:             joint(&RigJointName::L_LOWARM)?,
110:             joint(&RigJointName::R_LOWARM)?,
111:         ],
112:         wrists: [
113:             joint(&RigJointName::L_WRIST)?,
114:             joint(&RigJointName::R_WRIST)?,
115:         ],
116:         hips: [
117:             joint(&RigJointName::L_UPLEG)?,
118:             joint(&RigJointName::R_UPLEG)?,
119:         ],
120:         knees: [
121:             joint(&RigJointName::L_LOWLEG)?,
122:             joint(&RigJointName::R_LOWLEG)?,
123:         ],
124:         neck: joint(&RigJointName::C_NECK)?,
125:     };

125:     };
126:     let vertices: Vec<_> = input
127:         .positions
128:         .iter()
129:         .map(|p| p.map(|v| v * 100.0))
