5: /// Recovery available at this performance snapshot, not a permanent capability.
6: #[derive(Clone, Copy, Debug, PartialEq, serde::Serialize)]
7: #[serde(into = "Option<AnimationElapsed>")]
8: pub enum RecoveryTime {
9:     After(AnimationElapsed),
10:     CannotRecover,
11: }
12: 
13: impl RecoveryTime {
14:     pub fn available(self) -> Option<AnimationElapsed> {
15:         match self {
16:             Self::After(elapsed) => Some(elapsed),
17:             Self::CannotRecover => None,
18:         }
19:     }
20: }
21: 
22: impl From<RecoveryTime> for Option<AnimationElapsed> {
23:     fn from(recovery: RecoveryTime) -> Self {
24:         recovery.available()
25:     }
26: }
27: 
28: /// The remaining combat effectiveness after all wheel contributions, not a
29: /// separate fatigue penalty. Limb injury effects remain independently modeled.
30: pub fn combat_incapacitation_performance(incapacitation: f32) -> FractionResult<UnitInterval> {
31:     UnitInterval::from_fraction(1.0 - incapacitation.clamp(0.0, 1.0))
32: }
33: 
34: /// Zero recovery needs no performance. Positive recovery is unavailable at zero
35: /// performance; finite arithmetic overflow remains a timing error.
36: pub fn incapacitation_adjusted_recovery_seconds(
37:     base_recovery: AnimationElapsed,
38:     performance: UnitInterval,
39: ) -> ElapsedResult<RecoveryTime> {
40:     if base_recovery.is_zero() {
41:         return Ok(RecoveryTime::After(AnimationElapsed::ZERO));
42:     }
43:     let performance = performance.fraction().clamp(0.0, 1.0);
44:     if performance == 0.0 {
45:         return Ok(RecoveryTime::CannotRecover);
46:     }
47:     let seconds = base_recovery.seconds() / performance;
48:     if !seconds.is_finite() {
49:         return Err(ElapsedError::Overflow);
50:     }
51:     Ok(RecoveryTime::After(AnimationElapsed::from_seconds(
52:         seconds,
53:     )?))
54: }
