197: fn paint_incapacitation_wheel(
198:     painter: &egui::Painter,
199:     center: Pos2,
200:     state: &TacticalCombatState,
201:     sources: TacticalIncapacitationSources,
202:     radius: f32,
203:     width: f32,
204: ) {
205:     painter.circle_stroke(
206:         center,
207:         radius,
208:         Stroke::new(
209:             width,
210:             Color32::from_rgba_unmultiplied(0x10, 0x12, 0x16, 150),
211:         ),
212:     );
213: 
214:     if state.is_incapacitated() {
215:         painter.circle_stroke(
216:             center,
217:             radius,
218:             Stroke::new(
219:                 width + 6.0,
220:                 Color32::from_rgba_unmultiplied(0xc8, 0x47, 0x47, 70),
221:             ),
222:         );
223:     }
224: 
225:     let mut cursor = -std::f32::consts::FRAC_PI_2;
226:     let mut remaining = 1.0_f32;
227:     for (raw_amount, color) in forecast_wheel_segments(sources, state.projected_increase) {
228:         let Some(amount) = visible_incapacitation_wheel_amount(raw_amount, remaining) else {
229:             continue;
230:         };
231:         let end = cursor + amount * std::f32::consts::TAU;
232:         let steps = (amount * INCAPACITATION_WHEEL_RESOLUTION).ceil().max(2.0) as usize;
233:         let points = (0..=steps)
234:             .map(|step| {
235:                 let angle = cursor + (end - cursor) * step as f32 / steps as f32;
236:                 Pos2::new(
237:                     center.x + radius * angle.cos(),
238:                     center.y + radius * angle.sin(),
239:                 )
240:             })
241:             .collect();
242:         painter.add(egui::Shape::line(points, Stroke::new(width, color)));
243:         cursor = end;
244:         remaining -= amount;
245:         if remaining <= 0.0 {
246:             break;
247:         }
248:     }
249: }
