48: impl TacticalCombatState {
49:     /// Charge work and update readiness atomically, including between server ticks.
50:     pub fn charge_work(
51:         &mut self,
52:         workload: CombatActionWorkload,
53:         endurance: f32,
54:         parameters: CombatFatigueParameters,
55:     ) {
56:         let before = self.fatigue;
57:         apply_combat_workload(&mut self.fatigue, workload, endurance, parameters);
58:         self.incapacitation = (self.incapacitation + self.fatigue - before).max(0.0);
59:     }
60: 
61:     /// Returns the source values represented by the tactical incapacitation
62:     /// wheel. Pain, blood loss, and fatigue are recomputed live in combat; other
63:     /// strategic sources retain their enrollment-time breakdown.
64:     pub fn incapacitation_sources(
65:         &self,
66:         total_limb_damage: f32,
67:         will_check: f32,
68:     ) -> TacticalIncapacitationSources {
69:         let remaining_blood =
70:             (self.starting_blood_fraction - self.blood_loss_fraction).clamp(0.0, 1.0);
71:         TacticalIncapacitationSources {
72:             pain: pain_incapacitation(total_limb_damage, will_check),
73:             acute_trauma: self.acute_trauma.max(0.0),
74:             blood_loss: blood_loss_incapacitation(remaining_blood, 1.0),
75:             fear: self.starting_fear.max(0.0),
76:             fatigue: self.fatigue.clamp(0.0, 1.0),
77:             hunger: self.starting_hunger.max(0.0),
78:             thirst: self.starting_thirst.max(0.0),
79:             thermal: self.starting_thermal.max(0.0),
80:             imbalance: self.imbalance.max(0.0),
81:             encumbrance: self.encumbrance.max(0.0),
82:         }
83:     }
84: 
85:     /// Derives readiness from the one replicated incapacitation value.
86:     ///
87:     /// Readiness is intentionally not stored separately: clients, authority
88:     /// checks, AI, and mission resolution therefore cannot observe divergent
89:     /// boolean/component copies of the same state.
90:     pub fn incapacitation_status(&self) -> IncapacitationStatus {
91:         match self.incapacitation {
92:             total if total >= 1.0 => IncapacitationStatus::Incapacitated,
93:             total if total > 0.5 => IncapacitationStatus::Staggered,
94:             _ => IncapacitationStatus::Ready,
95:         }
96:     }
97: 
98:     pub fn is_incapacitated(&self) -> bool {
99:         self.incapacitation_status() == IncapacitationStatus::Incapacitated
100:     }
101: }
