62:     pub fn contact_timing(
63:         self,
64:         authored_windup: AnimationElapsed,
65:     ) -> AnimationValueResult<MeleeContactTiming> {
66:         // This is the original contact/delay kernel, including its zero-sign
67:         // normalization. The outcome itself remains explicit at every caller.
68:         let predicted = match self {
69:             Self::ArrivesIn(arrival) => arrival.seconds(),
70:             Self::NotNeeded | Self::CannotArrive => 0.0,
71:         };
72:         let authored = authored_windup.seconds();
73:         let contact = authored.max(predicted).max(0.0);
74:         let delay = (contact - authored.max(0.0)).max(0.0);
75:         Ok(MeleeContactTiming {
76:             delay: AnimationElapsed::from_seconds(delay)?,
77:             contact: AnimationElapsed::from_seconds(contact)?,
78:         })
79:     }
