95: pub fn melee_lunge_arrival(
96:     lunge: MeleeLunge,
97:     forward_speed_metres_per_second: adventuresim_core::linear_speed::NonnegativeSpeed,
98:     forward_acceleration_metres_per_second_squared: ForwardLungeAcceleration,
99:     quickstep_duration: crate::animation::PositiveAnimationDuration,
100: ) -> AnimationValueResult<MeleeLungeArrival> {
101:     let fixed_tick_safety = 1.0 / crate::animation::locomotion_sample_rate().hertz();
102:     let seconds = match lunge {
103:         MeleeLunge::None => return Ok(MeleeLungeArrival::NotNeeded),
104:         MeleeLunge::Forward { distance_metres } => {
105:             if distance_metres <= 0.0 {
106:                 return Ok(MeleeLungeArrival::ArrivesIn(
107:                     AnimationElapsed::from_seconds(fixed_tick_safety)?,
108:                 ));
109:             }
110:             let speed = forward_speed_metres_per_second.metres_per_second();
111:             let acceleration =
112:                 forward_acceleration_metres_per_second_squared.metres_per_second_squared();
113:             if !distance_metres.is_finite() {
114:                 return Err(AnimationValueError::NonFinite {
115:                     quantity: AnimationQuantity::Elapsed,
116:                 });
117:             }
118:             if speed <= 0.0 || acceleration <= 0.0 {
119:                 return Ok(MeleeLungeArrival::CannotArrive);
120:             }
121:             let acceleration_seconds = speed / acceleration;
122:             let acceleration_distance = 0.5 * acceleration * acceleration_seconds.powi(2);
123:             let travel_seconds = if distance_metres <= acceleration_distance {
124:                 (2.0 * distance_metres.max(0.0) / acceleration).sqrt()
125:             } else {
126:                 acceleration_seconds + (distance_metres - acceleration_distance) / speed
127:             };
128:             travel_seconds + fixed_tick_safety
129:         }
130:         MeleeLunge::Quickstep { .. } => quickstep_duration.seconds().max(0.0) + fixed_tick_safety,
131:     };
132:     if !seconds.is_finite() {
133:         return Err(AnimationValueError::Overflow {
134:             quantity: AnimationQuantity::Elapsed,
135:         });
136:     }
137:     Ok(MeleeLungeArrival::ArrivesIn(
138:         AnimationElapsed::from_seconds(seconds)?,
139:     ))
140: }
