142: pub fn conservative_forward_lunge_acceleration(
143:     motor: &crate::combat_config::CharacterMotorConfig,
144: ) -> AnimationValueResult<ForwardLungeAcceleration> {
145:     let minimum_healthy_strength_scale = 1.0 / motor.reference_leg_strength.max(1.0);
146:     let drive = motor.reference_ground_drive_force_newtons * minimum_healthy_strength_scale
147:         / motor.fallback_character_mass_kg.max(1.0);
148:     ForwardLungeAcceleration::from_metres_per_second_squared(
149:         drive.min(motor.gravity_metres_per_second_squared * motor.traction_coefficient),
150:     )
