563:     facts: RangedIntentFacts,
564: ) -> Result<ValidatedRangedShot, RangedIntentRejection> {
565:     if facts.target == Some(facts.attacker) {
566:         return Err(RangedIntentRejection::SelfTarget);
567:     }
568:     let Some(attacker_side) = facts.attacker_side else {
569:         return Err(RangedIntentRejection::MissingSide);
570:     };
571:     let Some(attacker_incapacitated) = facts.attacker_incapacitated else {
572:         return Err(RangedIntentRejection::MissingCombatState);
573:     };
574:     if attacker_incapacitated {
575:         return Err(RangedIntentRejection::Incapacitated);
576:     }
577:     if !facts.weapon_is_ranged || !facts.weapon_range.is_finite() || facts.weapon_range <= 0.0 {
578:         return Err(RangedIntentRejection::NotRanged);
579:     }
580:     if facts.target.is_some() {
581:         let Some(target_side) = facts.target_side else {
582:             return Err(RangedIntentRejection::MissingSide);
583:         };
584:         let Some(target_incapacitated) = facts.target_incapacitated else {
585:             return Err(RangedIntentRejection::MissingCombatState);
586:         };
587:         if attacker_side == target_side {
588:             return Err(RangedIntentRejection::FriendlyTarget);
589:         }
590:         if target_incapacitated {
591:             return Err(RangedIntentRejection::Incapacitated);
592:         }
593:         if !facts.separation.is_some_and(|distance| {
594:             distance.is_finite() && distance <= facts.weapon_range + facts.range_latency_tolerance
595:         }) {
596:             return Err(RangedIntentRejection::OutOfRange);
597:         }
598:         if facts.target_in_aim_cone != Some(true) {
599:             return Err(RangedIntentRejection::OutsideAimCone);
600:         }
601:     }
602:     if !facts.authority_permits {
603:         return Err(RangedIntentRejection::Windup);
