1: //! Shell primitives retain their own topology, UVs, skin and surface textures.
2: use super::*;
3: pub(super) type Views = (usize, usize, usize, Option<(usize, usize)>);
4: pub(super) struct Writer<'a> {
5:     pub buffer: &'a mut BufferBuilder,
6:     pub primitives: &'a mut Vec<Value>,
7:     pub materials: &'a mut Vec<Value>,
8:     pub body_skin: [usize; 2],
9:     pub textures: &'a mut textures::TextureImages,
10: }
11: impl Writer<'_> {
12:     pub fn append(
13:         &mut self,
14:         shells: &[RiggedShell<'_>],
15:         views: Vec<Views>,
16:         mut accessor: impl FnMut(usize, u32, usize, &str, Option<([f32; 3], [f32; 3])>) -> usize,
17:     ) {
18:         for (shell, (position_view, normal_view, index_view, skin_views)) in
19:             shells.iter().zip(views)
20:         {
21:             let (minimum, maximum) = position_bounds(shell.positions);
22:             let shell_position_accessor = accessor(
23:                 position_view,
24:                 5_126,
25:                 shell.positions.len(),
26:                 "VEC3",
27:                 Some((minimum, maximum)),
28:             );
29:             let shell_index_accessor =
30:                 accessor(index_view, 5_125, shell.faces.len() * 3, "SCALAR", None);
31:             let shell_normal_accessor =
32:                 accessor(normal_view, 5_126, shell.normals.len(), "VEC3", None);
33:             let (shell_joints_0, shell_weights_0) = if let Some((joints_0, weights_0)) = skin_views
34:             {
35:                 (
36:                     accessor(joints_0, 5_123, shell.positions.len(), "VEC4", None),
37:                     accessor(weights_0, 5_126, shell.positions.len(), "VEC4", None),
38:                 )
39:             } else {
40:                 (self.body_skin[0], self.body_skin[1])
41:             };
42:             let material = self.materials.len();
43:             let mut primitive = json!({
44:                 "attributes": {
45:                     "POSITION": shell_position_accessor,
46:                     "NORMAL": shell_normal_accessor,
47:                     "JOINTS_0": shell_joints_0,
48:                     "WEIGHTS_0": shell_weights_0,
49:                 },
50:                 "indices": shell_index_accessor,
51:                 "material": material,
52:             });
53:             if let Some(uv) = shell.texcoords.or_else(|| shell.surface.map(|(uv, _)| uv)) {
54:                 let view = self
55:                     .buffer
56:                     .push(&f32_bytes(uv.iter().flatten().copied()), Some(34_962));
57:                 primitive["attributes"]["TEXCOORD_0"] =
58:                     accessor(view, 5_126, uv.len(), "VEC2", None).into();
59:             }
60:             self.primitives.push(primitive);
61:             let mut material = json!({
62:                 "name": shell.name,
63:                 "doubleSided": true,
64:                 "pbrMetallicRoughness": {
65:                     "baseColorFactor": linear_base_color(shell.base_color),
66:                     "metallicFactor": shell.metallic,
67:                     "roughnessFactor": shell.roughness,
68:                 }
69:             });
70:             if let Some(textures) = shell.textures.clone() {
71:                 self.textures.apply(textures, self.buffer, &mut material);
72:             }
73:             if let Some(finish) = shell.textile_finish {
74:                 self.textures.apply_textile_finish(finish, &mut material);
75:             }

