 14 #[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
 15 pub struct OrderedSigilSpec {
 16     pub allow_exact: bool,
 17     pub allow_before: bool,
 18     pub allow_adjacent: bool,
 19     pub allow_not_at: bool,
 20     pub max_clues: u8,
 21 }
 22 
 23 impl Default for OrderedSigilSpec {
 24     fn default() -> Self {
 25         Self {
 26             allow_exact: true,
 27             allow_before: true,
 28             allow_adjacent: true,
 29             allow_not_at: true,
 30             max_clues: 4,
 31         }
 32     }
 33 }
 34 
 35 impl OrderedSigilSpec {
 36     pub fn validate(self) -> Result<Self, &'static str> {
 37         if !(self.allow_exact || self.allow_before || self.allow_adjacent || self.allow_not_at) {
 38             return Err("ordered-sigil spec must enable at least one clue family");
 39         }
 40         if !(1..=8).contains(&self.max_clues) {
 41             return Err("ordered-sigil max clues must be between one and eight");
 42         }
 43         Ok(self)
 44     }
 45 
 46     fn allows(self, clue: &OrderedSigilClue) -> bool {
 47         match clue {
 48             OrderedSigilClue::Exact { .. } => self.allow_exact,
 49             OrderedSigilClue::Before { .. } => self.allow_before,
 50             OrderedSigilClue::Adjacent { .. } => self.allow_adjacent,
 51             OrderedSigilClue::NotAt { .. } => self.allow_not_at,
 52         }
 53     }
 54 }
