 56 impl OrderedSigilClue {
 57     pub fn text(&self) -> String {
 58         match self {
 59             Self::Exact { sigil, position } => {
 60                 format!("The {} belongs in place {}.", sigil.label(), position + 1)
 61             }
 62             Self::Before { first, second } => format!(
 63                 "The {} stands somewhere before the {}.",
 64                 first.label(),
 65                 second.label()
 66             ),
 67             Self::Adjacent { first, second } => format!(
 68                 "The {} and {} stand beside one another.",
 69                 first.label(),
 70                 second.label()
 71             ),
 72             Self::NotAt { sigil, position } => {
 73                 format!(
 74                     "The {} does not belong in place {}.",
 75                     sigil.label(),
 76                     position + 1
 77                 )
 78             }
 79         }
