112 impl OrderedSigilPuzzle {
113     pub fn generate(seed: Seed) -> Self {
114         Self::generate_with_spec(seed, OrderedSigilSpec::default())
115             .expect("current ordered-sigil rules are supported")
116     }
117 
118     pub fn generate_versioned(rules_version: u16, seed: Seed) -> Result<Self, &'static str> {
119         if rules_version != ORDERED_SIGIL_RULES_VERSION {
120             return Err("unsupported ordered-sigil rules version");
121         }
122         Self::generate_with_spec(seed, OrderedSigilSpec::default())
123     }
124 
125     pub fn generate_with_spec(seed: Seed, spec: OrderedSigilSpec) -> Result<Self, &'static str> {
126         let spec = spec.validate()?;
127         const ORDERED_SIGIL_GENERATION_DOMAIN: fabelgeist_determinism::StreamId =
128             fabelgeist_determinism::StreamId::new("puzzle.ordered_sigil");
129         let mut rng = ORDERED_SIGIL_GENERATION_DOMAIN.rng(seed, &[]);
130         let mut solution = Sigil::ALL;
131         for end in (1..solution.len()).rev() {
132             let selected = rng.index(end + 1);
133             solution.swap(end, selected);
134         }
135 
136         let (clues, _) = minimum_clues(&solution, spec)?;
137         let puzzle = Self {
138             rules_version: ORDERED_SIGIL_RULES_VERSION,
139             seed,
140             spec,
141             solution,
142             clues,
143         };
144         puzzle.validate()?;
145         Ok(puzzle)
146     }
147 
148     pub fn projection(&self) -> OrderedSigilProjection {
149         OrderedSigilProjection {
150             rules_version: self.rules_version,
151             sigils: Sigil::ALL,
152             clues: self.clues.clone(),
153         }
154     }
155 
156     pub fn validate(&self) -> Result<(), &'static str> {
157         if self.rules_version != ORDERED_SIGIL_RULES_VERSION {
158             return Err("unsupported ordered-sigil rules version");
159         }
160         self.spec.validate()?;
161         if self.clues.len() > usize::from(self.spec.max_clues)
162             || self.clues.iter().any(|clue| !self.spec.allows(clue))
163         {
164             return Err("ordered-sigil clues violate their generation spec");
165         }
166         if !is_permutation(&self.solution) {
167             return Err("ordered-sigil solution is malformed");
168         }
169         if self.clues.iter().any(|clue| match clue {
170             OrderedSigilClue::Exact { position, .. } | OrderedSigilClue::NotAt { position, .. } => {
171                 usize::from(*position) >= ORDERED_SIGIL_COUNT
172             }
173             OrderedSigilClue::Before { first, second }
174             | OrderedSigilClue::Adjacent { first, second } => first == second,
175         }) {
176             return Err("ordered-sigil clue coordinates are malformed");
177         }
178         let found = solutions(&self.clues, 2);
179         if found.len() != 1 || found[0] != self.solution {
180             return Err("ordered-sigil clues do not prove the canonical solution");
181         }
182         Ok(())
183     }
184 
185     pub fn check(&self, submission: &OrderedSigilSubmission) -> Result<bool, SubmissionError> {
186         if !is_permutation(&submission.ordering) {
187             return Err(SubmissionError::DuplicateSigil);
188         }
189         Ok(submission.ordering == self.solution)
190     }
191 }
