193 pub fn true_clue_pool(solution: &[Sigil; ORDERED_SIGIL_COUNT]) -> Vec<OrderedSigilClue> {
194     let mut pool = Vec::with_capacity(39);
195     // Canonical relational-first order is also the final deterministic
196     // tie-break after cardinality, Exact count, and NotAt count.
197     for left in 0..ORDERED_SIGIL_COUNT {
198         for right in (left + 1)..ORDERED_SIGIL_COUNT {
199             pool.push(OrderedSigilClue::Before {
200                 first: solution[left],
201                 second: solution[right],
202             });
203         }
204     }
205     for left in 0..(ORDERED_SIGIL_COUNT - 1) {
206         pool.push(OrderedSigilClue::Adjacent {
207             first: solution[left],
208             second: solution[left + 1],
209         });
210     }
211     for (position, sigil) in solution.iter().copied().enumerate() {
212         for wrong in 0..ORDERED_SIGIL_COUNT {
213             if wrong != position {
214                 pool.push(OrderedSigilClue::NotAt {
215                     sigil,
216                     position: wrong as u8,
217                 });
218             }
219         }
220     }

