507 fn direct_demo_challenge_redirect(
508     challenges: &[BackendChallenge],
509     road_challenges: &[BackendRoadChallenge],
510     character_id: u64,
511 ) -> Option<String> {
512     if road_challenges.iter().any(|challenge| {
513         challenge.owner_character_id == character_id && challenge.active && challenge.open
514     }) {
515         return None;
516     }
517     let mut playable = challenges.iter().filter(|challenge| {
518         challenge.owner_character_id == character_id
519             && challenge.active
520             && challenge.open
521             && !challenge.solved
522             && is_direct_demo_challenge_id(&challenge.id, character_id)
523     });
524     let challenge = playable.next()?;
525     playable
526         .next()
527         .is_none()
528         .then(|| format!("/quests/{}/challenges/{}", challenge.case_id, challenge.id))
529 }
