155: pub(crate) fn consume_autoresolve_ammunition(
156:     ctx: &ReducerContext,
157:     character_id: u64,
158:     mut quantity: u32,
159: ) {
160:     let stacks: Vec<_> = ctx
161:         .db
162:         .inventory_item()
163:         .character_and_item_id()
164:         .filter((character_id, "arrow"))
165:         .collect();
166:     for mut stack in stacks {
167:         if quantity == 0 {
168:             break;
169:         }
170:         let consumed = quantity.min(stack.quantity);
171:         quantity -= consumed;
172:         stack.quantity -= consumed;
173:         if stack.quantity == 0 {
174:             ctx.db.inventory_item().id().delete(stack.id);
175:         } else {
176:             ctx.db.inventory_item().id().update(stack);
177:         }
178:     }
