11: pub fn report_contract(
12:     ctx: &ReducerContext,
13:     character_id: u64,
14:     contract_id: String,
15: ) -> Result<(), String> {
16:     require_strategic_character_authority(ctx, character_id)?;
17:     crate::character::require_living_character(ctx, character_id)?;
18:     let character = ctx
19:         .db
20:         .character()
21:         .id()
22:         .find(character_id)
23:         .ok_or("Character not found")?;
24:     let party_id = character.party_id.ok_or("Must be in a party")?;
25:     let mut party = ctx
26:         .db
27:         .party_authority()
28:         .id()
29:         .find(&party_id)
30:         .ok_or("Party not found")?;
31:     if party.active_contract_id.as_deref() != Some(&contract_id) {
32:         return Err("This is not the party's active quest".into());
33:     }
34:     let mut quest = ctx
35:         .db
36:         .contract_authority()
37:         .id()
38:         .find(&contract_id)
39:         .ok_or("Quest not found")?;
40:     quest.parsed_state().map_err(|error| error.to_string())?;
41:     if quest.status != ContractStatus::ReadyToReport
42:         || quest.accepted_by.as_ref() != Some(&party_id)
43:     {
44:         return Err("The quest has not been completed by this party".into());
45:     }
46:     if quest.paid_at_minute.is_some() {
47:         return Err("This contract has already been paid".into());
48:     }
49:     if character.current_settlement_id.as_ref() != Some(&quest.settlement_id) {
50:         return Err("Return to the questgiver's settlement to claim the reward".into());
51:     }
52:     consume_contract_interaction(
53:         ctx,
54:         &contract_id,
55:         &party_id,
56:         ContractInteractionStage::Report,
57:     )?;
58:     let reported_at_minute = crate::time::refresh_clock(ctx)?;
59: 
60:     let reward = quest.gold_reward.max(0) as u64;
61:     if reward > 0 {
62:         credit_party_currency(ctx, &party_id, &quest.settlement_id, reward as u32)?;
63:         let recipients = living_party_member_ids(ctx, &party_id);
64:         let recipient_count = recipients.len().max(1) as u64;
65:         let share = reward / recipient_count;
66:         for recipient in recipients {
67:             credit_party_stake(ctx, &party_id, recipient, share)?;
68:         }
69:         credit_party_reserve(ctx, &party_id, reward % recipient_count)?;
70:     }
71:     let total_xp = quest.xp_reward.max(0) as u32;
72:     let members = living_party_member_ids(ctx, &party_id);
73:     let xp_per_member = total_xp / members.len().max(1) as u32;
74:     for member_id in members {
75:         if let Some(mut member) = ctx.db.character().id().find(member_id) {
76:             member.xp = member.xp.saturating_add(xp_per_member);
77:             member.level = 1 + member.xp / 100;
78:             ctx.db.character().id().update(member);
79:         }
80:     }
81:     quest.status = ContractStatus::Paid;
82:     quest.paid_at_minute = Some(reported_at_minute);
83:     ctx.db.contract_authority().id().update(quest.clone());
84: 
85:     party.active_contract_id = None;
86:     ctx.db.party_authority().id().update(party);
87:     let obsolete_requests: Vec<u64> = ctx
88:         .db
89:         .party_action_request_authority()
90:         .party_id()
91:         .filter(&party_id)
92:         .filter(|request| request.action_kind == "report_contract")
93:         .map(|request| request.id)
94:         .collect();
95:     for request_id in obsolete_requests {
96:         ctx.db
97:             .party_action_request_authority()
98:             .id()
99:             .delete(request_id);
100:     }
101:     ensure_settlement_activity_inner(ctx, &quest.settlement_id)?;
102:     Ok(())
103: }
