704:     /// Training-only contribution on the shared five-point curve. `max_hours`
705:     /// is the documented asymptotic calibration; half of it is the half-rank
706:     /// point used consistently by simulation, persistence, and UI.
707:     pub fn training_rank(self, hours: f32) -> f32 {
708:         let hours = if hours.is_finite() {
709:             hours.max(0.0)
710:         } else {
711:             0.0
712:         };
713:         MAX_CHECK * (hours / (hours + self.max_hours() * 0.5))
714:     }
715: 
716:     /// Effective hours at which the shared training curve reaches `rank`.
717:     ///
718:     /// Rank five is the curve's asymptote and therefore has no finite hours
719:     /// boundary.
720:     pub fn hours_for_rank(self, rank: f32) -> f32 {
721:         let rank = if rank.is_finite() {
722:             rank.clamp(0.0, MAX_CHECK)
723:         } else {
724:             0.0
725:         };
726:         if rank >= MAX_CHECK {
775:             | Self::Smithing => GoverningAptitudes::agility(LimbWeights::both_arms()),
776:         }
777:     }
