60: #[reducer]
61: pub fn request_party_action(
62:     ctx: &ReducerContext,
63:     requester_id: u64,
64:     action_kind: String,
65:     summary: String,
66:     payload: String,
67: ) -> Result<(), String> {
68:     crate::character::require_living_character(ctx, requester_id)?;
69:     let requester = ctx
70:         .db
71:         .character()
72:         .id()
73:         .find(requester_id)
74:         .ok_or("Character not found")?;
75:     let party_id = requester.party_id.ok_or("Character has no party")?;
76:     let party = ctx
77:         .db
78:         .party_authority()
79:         .id()
80:         .find(&party_id)
81:         .ok_or("Party not found")?;
82:     if party.leader_id == requester_id {
83:         return Err("The party leader does not need to request permission".into());
84:     }
85:     let allowed = [
86:         "travel",
87:         "kick",
88:         "add_role",
89:         "edit_role",
90:         "delete_role",
91:         "accept_join",
92:         "reject_join",
93:         "accept_contract",
94:         "abandon_contract",
95:         "report_contract",
96:         "autoresolve",
97:         "party_checks",
98:         "party_inventory",
99:         "disband_party",
100:         "initiate_combat",
101:         "cancel_mission",
102:         "investigate",
103:     ];
104:     if !allowed.contains(&action_kind.as_str()) {
105:         return Err("Unknown party action request".into());
106:     }
107:     // Travel destinations supersede one another. Inventory target/staging edits
108:     // are intentionally coalesced to one notification per requesting member.
109:     if action_kind == "travel" || action_kind == "party_inventory" {
110:         let old: Vec<_> = ctx
111:             .db
112:             .party_action_request_authority()
113:             .requester_id()
114:             .filter(requester_id)
115:             .filter(|request| request.party_id == party_id && request.action_kind == action_kind)
116:             .map(|request| request.id)
117:             .collect();
118:         for id in old {
119:             ctx.db.party_action_request_authority().id().delete(id);
120:         }
121:     }
122:     ctx.db
123:         .party_action_request_authority()
124:         .insert(PartyActionRequest {
125:             id: 0,
126:             gateway_bucket: 0,
127:             party_id,
128:             requester_id,
129:             action_kind,
130:             summary: summary.trim().to_string(),
131:             payload,
132:         });
133:     Ok(())
134: }
