10: pub const PARTY_CHARISMA_BASELINE: f32 = 2.5;
11: pub const PARTY_CHARISMA_SUPPORT_WEIGHT: f32 = 0.5;
12: pub const PARTY_CHARISMA_COORDINATION_LIMIT: f32 = 1.125;
