18: /// Combines party-wide skill checks with diminishing returns. The strongest
19: /// contributor counts fully, the next at half value, the third at one third,
20: /// and so on, matching the aggregate check described by the morale design.
21: pub fn aggregate_party_check(values: impl IntoIterator<Item = f32>) -> f32 {
22:     let mut values: Vec<f32> = values
23:         .into_iter()
24:         .filter(|value| value.is_finite() && *value > 0.0)
25:         .collect();
26:     values.sort_by(|left, right| right.total_cmp(left));
27:     values
28:         .into_iter()
29:         .enumerate()
30:         .map(|(index, value)| value / (index + 1) as f32)
31:         .sum()
32: }
