34: /// The authoritative trained-mental Religion check for one tradition.
35: /// Religion has no equipment or fatigue term, so the public strategic fields
36: /// are sufficient to reproduce the same check for a schedule preview.
37: pub fn religion_knowledge_check(
38:     effective_hours: f32,
39:     _instinct: f32,
40:     intelligence: f32,
41:     _focus: f32,
42:     head_health: f32,
43: ) -> f32 {
44:     let health = if head_health.is_finite() {
45:         head_health.clamp(0.0, 1.0)
46:     } else {
47:         0.0
48:     };
49:     Skill::Religion.capped_rank_for_aptitude(effective_hours, intelligence) * health
50: }
