52: /// The authoritative trained-mental Bestiary check for one creature category.
53: pub fn bestiary_knowledge_check(
54:     effective_hours: f32,
55:     _instinct: f32,
56:     intelligence: f32,
57:     _focus: f32,
58:     head_health: f32,
59: ) -> f32 {
