68: pub fn aggregate_party_contribution(current: &[f32], candidate: f32) -> f32 {
69:     let before = aggregate_party_check(current.iter().copied());
70:     let after = aggregate_party_check(current.iter().copied().chain([candidate]));
71:     (after - before).max(0.0)
72: }
73: 
74: /// Combines a lead practitioner's check with geometrically diminishing support.
75: ///
76: /// Values are sorted strongest-first. The leader has full weight, followed by
77: /// weights of 1/2, 1/4, 1/8, and so on. Combining the contributors as
78: /// complementary fractions of the five-point scale keeps the result bounded
79: /// without clamping it. With the 1/2 decay, all supporters together can have
80: /// at most the influence of one additional copy of the leader.
81: pub fn aggregate_bounded_party_check(values: impl IntoIterator<Item = f32>) -> f32 {
82:     let mut values: Vec<f32> = values
83:         .into_iter()
84:         .filter(|value| value.is_finite() && *value > 0.0)
85:         .map(|value| value.min(MAX_PARTY_CHECK))
86:         .collect();
87:     values.sort_by(|left, right| right.total_cmp(left));
88: 
89:     let unfilled_fraction = values
90:         .into_iter()
91:         .enumerate()
92:         .map(|(index, value)| {
93:             let weight = BOUNDED_PARTY_CHECK_SUPPORT_DECAY.powi(index as i32);
94:             (1.0 - value / MAX_PARTY_CHECK).powf(weight)
95:         })
96:         .product::<f32>();
97:     MAX_PARTY_CHECK * (1.0 - unfilled_fraction)
98: }
99: 
100: pub fn aggregate_bounded_party_contribution(current: &[f32], candidate: f32) -> f32 {
101:     let before = aggregate_bounded_party_check(current.iter().copied());
102:     let after = aggregate_bounded_party_check(current.iter().copied().chain([candidate]));
103:     (after - before).max(0.0)
104: }
105: 
106: /// Aggregate Command as a lead speaker supported (or burdened) by the party.
107: ///
108: /// The strongest member establishes the base check. Additional members provide
109: /// a rapidly saturating coordination benefit, then help or hinder according to
110: /// how far their individual check is above or below the neutral 2.5 baseline.
111: pub fn aggregate_party_command(values: impl IntoIterator<Item = f32>) -> f32 {
112:     let mut values: Vec<f32> = values
113:         .into_iter()
114:         .filter(|value| value.is_finite())
115:         .map(|value| value.clamp(0.0, 5.0))
116:         .collect();
117:     values.sort_by(|left, right| right.total_cmp(left));
118:     let Some((&leader, supporters)) = values.split_first() else {
119:         return 0.0;
120:     };
121:     if supporters.is_empty() {
122:         return leader;
123:     }
124:     let coordination = PARTY_CHARISMA_COORDINATION_LIMIT
125:         * (1.0 - PARTY_CHARISMA_COORDINATION_DECAY.powi(supporters.len() as i32));
126:     let support: f32 = supporters
127:         .iter()
128:         .map(|value| PARTY_CHARISMA_SUPPORT_WEIGHT * (value - PARTY_CHARISMA_BASELINE))
129:         .sum();
130:     (leader + coordination + support).clamp(0.0, 5.0)
131: }
132: 
133: pub fn aggregate_party_command_contribution(current: &[f32], candidate: f32) -> f32 {
134:     aggregate_party_command(current.iter().copied().chain([candidate]))
135:         - aggregate_party_command(current.iter().copied())
136: }
