116: pub fn refresh_character_capability(
117:     ctx: &ReducerContext,
118:     character_id: u64,
119: ) -> Result<CharacterCapabilities, String> {
120:     let capabilities = evaluate_character(ctx, character_id)?;
121:     let mut row = CharacterCapability::from((character_id, capabilities));
122:     let condition = ctx
123:         .db
124:         .character_strategic_condition()
125:         .character_id()
126:         .find(character_id);
127:     let combatant = load_combatant(
128:         ctx,
129:         character_id,
130:         condition.as_ref().map_or(0.0, |row| row.incapacitation),
131:         condition.as_ref().map_or(0.0, |row| row.pain),
132:         condition.as_ref().map_or(0.0, |row| row.blood_loss),
133:     )?;
134:     row.autoresolve_combat_power =
135:         adventuresim_core::autoresolve::autoresolve_combat_power(&combatant);
136:     if let Some(existing) = ctx
137:         .db
138:         .character_capability()
139:         .character_id()
140:         .find(character_id)
141:     {
142:         // Capability reads are currently refreshed lazily by the web layer. Avoid
143:         // emitting a table update when the derived value has not changed: that
144:         // update invalidates the SSE UI, which otherwise refreshes the same
145:         // capability again and creates a feedback loop.
146:         if existing != row {
147:             let old_band = existing.physiology.round().clamp(0.0, 5.0) as u8;
148:             let new_band = row.physiology.round().clamp(0.0, 5.0) as u8;
149:             if old_band != new_band {
150:                 crate::social::close_physiology_presence(ctx, character_id);
151:             }
152:             ctx.db.character_capability().character_id().update(row);
153:             if old_band != new_band {
154:                 crate::social::reset_familiarity_after_join(ctx, character_id);
155:             }
156:         }
157:     } else {
158:         ctx.db.character_capability().insert(row);
159:     }
160:     Ok(capabilities)
161: }
