483: /// Returns the startup-compiled, YAML-authoritative threat profile.
484: pub fn profile(id: ThreatId) -> ThreatProfile {
485:     // Process-lifetime cache compiled once from the immutable embedded catalog.
486:     // A new process/catalog build creates a fresh cache; consumers cannot mutate it.
487:     static PROFILES: OnceLock<BTreeMap<ThreatId, ThreatProfile>> = OnceLock::new();
488:     *PROFILES
489:         .get_or_init(|| {
490:             crate::quest_catalog::catalog()
491:                 .monsters()
492:                 .map(|monster| {
493:                     let id = ThreatId::try_new(&monster.id).expect("validated monster ID");
494:                     (id, compile_profile(id, monster))
495:                 })
496:                 .collect()
497:         })
498:         .get(&id)
499:         .expect("threat ID was validated against startup catalog")
500: }
