779: pub(crate) fn complete_bound_mission_success(
780:     ctx: &ReducerContext,
781:     mission_id: &str,
782: ) -> Result<bool, String> {
783:     let mut mission = ctx
784:         .db
785:         .mission_authority()
786:         .id()
787:         .find(mission_id.to_string())
788:         .ok_or("Mission authority not found")?;
789:     mission.parsed_state().map_err(|error| error.to_string())?;
790:     if mission.status == MissionAttemptStatus::Committed {
791:         return Ok(false);
792:     }
793:     if mission.status != MissionAttemptStatus::Bound {
794:         return Err("Mission attempt is no longer eligible for completion".into());
795:     }
796:     let mut candidates = Vec::new();
797:     for candidate in ctx
798:         .db
799:         .mission_outcome_candidate()
800:         .mission_id()
801:         .filter(&mission.id)
802:     {
803:         if mission_candidate_is_current(ctx, &mission, &candidate)? {
804:             candidates.push(candidate);
805:         }
806:     }
807:     let Some(selected) = sample_mission_candidate(&mission, candidates) else {
808:         mission.status = MissionAttemptStatus::Failed;
809:         mission.parsed_state().map_err(|error| error.to_string())?;
810:         ctx.db.mission_authority().id().update(mission);
